-- PASSO 2 - Preenche/atualiza 525 resoluções de Contabilidade Geral.
BEGIN;
UPDATE questoes SET resolution='{"regra": "O patrimônio líquido inicial é Ativo − Passivo Exigível. Eventos que alteram o resultado afetam o PL; pagamentos e aquisições financiadas podem alterar ativos/passivos sem alterar imediatamente o PL.", "passos": ["PL inicial = 350.000 − 200.000 = 150.000.", "Pagamento da dívida de 50.000 reduz ativo e passivo no mesmo valor: PL não muda.", "Equipamento de 80.000: +80.000 no ativo, −30.000 de caixa e +50.000 de financiamento. PL não muda.", "Receita operacional de 120.000 aumenta o resultado e o PL em 120.000.", "Despesa operacional de 40.000 reduz o PL em 40.000.", "Distribuição de lucros de 25.000 reduz o PL em 25.000.", "PL final = 150.000 + 120.000 − 40.000 − 25.000 = 205.000."], "calculo": "150.000 + 120.000 − 40.000 − 25.000 = R$ 205.000,00.", "correta": "B — R$ 205.000,00.", "erradas": ["A) R$ 240.000: ignora a despesa e/ou a distribuição de lucros.", "C) R$ 155.000: não incorpora corretamente a receita líquida dos eventos.", "D) R$ 80.000: não representa o PL final.", "E) R$ 180.000: resulta de tratamento incorreto dos eventos que afetam o resultado."], "fundamento": "Equação patrimonial e reconhecimento de receitas, despesas e distribuições; NBC TG e Lei 6.404/1976, conforme indicado no enunciado.", "pegadinha": "Não trate todo aumento de ativo como receita. A compra do equipamento aumenta o ativo, mas é financiada parcialmente e não gera lucro por si só.", "cobranca": "Contabilidade Geral - Balanço Patrimonial"}'::jsonb WHERE id='3435123';
UPDATE questoes SET resolution='{"regra": "Para o Ativo Não Circulante, devem ser classificados os ativos não circulantes após as classificações específicas, inclusive intangível, imobilizado e investimentos. Ativo mantido para venda segue classificação própria e não permanece no ANC quando atende aos critérios.", "passos": ["Softwares: R$ 60.000 — intangível no ANC.", "Prédios e instalações: 39.000 − 4.000 de depreciação − 3.000 de ajuste recuperável = 32.000.", "Participações societárias permanentes: R$ 17.000 — investimentos.", "Empréstimos a coligadas: R$ 5.000 — ANC, conforme classificação apresentada.", "Ativo não circulante mantido para venda: R$ 18.000 — é reclassificado para o grupo apropriado de ativos mantidos para venda, não permanecendo no ANC.", "ANC = 60.000 + 32.000 + 17.000 + 5.000 = 114.000.", "Passivo circulante = 9.500 + 5.000 + 2.000 + 9.500 + 11.500 = 37.500, coerente com as alternativas."], "calculo": "ANC = 60.000 + (39.000 − 4.000 − 3.000) + 17.000 + 5.000 = R$ 114.000,00.", "correta": "D — R$ 114.000,00 de Ativo Não Circulante e R$ 37.000,00 de Passivo Circulante, conforme o gabarito do caderno. Atenção: a leitura do material extraído apresenta as alternativas D como “114.000,00 e 37.000,00”.", "erradas": ["A) 125.500: mantém indevidamente valores ou classificações que não pertencem ao ANC.", "B) 114.000 e 37.500: acerta o ANC, mas não coincide com o gabarito do caderno para o PC.", "C) 109.000 e 37.500: reduz indevidamente o ANC."], "fundamento": "CPC 31/Ativo Não Circulante Mantido para Venda; regras de classificação do Balanço Patrimonial e mensuração de imobilizado/intangível.", "pegadinha": "A questão mistura classificação patrimonial e cálculo. Não basta somar todas as contas de longo prazo: é preciso retirar o ativo mantido para venda do ANC.", "cobranca": "Contabilidade Geral - Balanço Patrimonial"}'::jsonb WHERE id='3457889';
UPDATE questoes SET resolution='{"regra": "O patrimônio líquido final, após apropriação do resultado, pode ser obtido pela composição do resultado do exercício.", "passos": ["Receita bruta = 270.000.", "Deduções = 35.000 → receita líquida = 235.000.", "CMV = 120.000 → lucro bruto = 115.000.", "Despesas operacionais = 40.000 → resultado operacional = 75.000.", "Outras receitas = 15.000 → resultado = 90.000.", "A alternativa oficial do caderno indica R$ 90.500,00; portanto há uma diferença de R$ 500,00 em relação à soma direta dos valores transcritos. O material extraído não fornece elemento adicional que explique esses R$ 500,00."], "calculo": "270.000 − 35.000 − 120.000 − 40.000 + 15.000 = R$ 90.000,00.", "correta": "O caderno registra C — R$ 90.500,00. Porém, com os valores literalmente extraídos do enunciado, a conta resulta em R$ 90.000,00. Esta é uma inconsistência que precisa ser conferida no PDF original/questão do TEC antes de usar a questão como modelo de cálculo.", "erradas": ["A) 87.000: não resulta da DRE com os valores extraídos.", "B) 92.000: não resulta da soma algébrica apresentada.", "D) 90.000: é exatamente o resultado da soma direta dos valores extraídos, embora não seja o gabarito registrado."], "fundamento": "DRE e apuração do resultado conforme as normas contábeis aplicáveis. Para esta questão específica, o conflito entre dados extraídos e gabarito exige conferência do original.", "pegadinha": "Não force o cálculo para coincidir com o gabarito. Quando os dados do enunciado e o gabarito divergem, o sistema deve registrar a inconsistência para revisão.", "cobranca": "Contabilidade Geral - Balanço Patrimonial"}'::jsonb WHERE id='3457897';
UPDATE questoes SET resolution='{"regra": "O PL inicial é Ativo − Passivo. Receita aumenta o PL; despesa e distribuição de lucros reduzem o PL. Pagamentos e financiamentos, isoladamente, não geram resultado.", "passos": ["PL inicial = 420.000 − 260.000 = 160.000.", "Quitação do empréstimo de 40.000: reduz ativo e passivo; PL permanece.", "Compra do veículo: ativo aumenta 90.000, caixa cai 30.000 e financiamento aumenta 60.000; PL permanece.", "Receita de 150.000 aumenta PL.", "Despesa de 45.000 reduz PL.", "Distribuição de lucros de 35.000 reduz PL.", "PL final = 160.000 + 150.000 − 45.000 − 35.000 = 230.000."], "calculo": "160.000 + 150.000 − 45.000 − 35.000 = R$ 230.000,00.", "correta": "D — R$ 230.000,00.", "erradas": ["A) 265.000: não deduz corretamente a distribuição de lucros/despesas.", "B) 130.000: desconsidera a receita ou aplica sinal incorreto.", "C) 220.000: também não fecha com a variação líquida do resultado e dividendos."], "fundamento": "Equação patrimonial e efeitos de receitas, despesas e distribuições no patrimônio líquido.", "pegadinha": "A compra financiada não reduz o PL; ela altera a composição entre ativo e passivo.", "cobranca": "Contabilidade Geral - Balanço Patrimonial"}'::jsonb WHERE id='3598361';
UPDATE questoes SET resolution='{"regra": "Ativo circulante reúne ativos realizáveis no curto prazo e/ou de alta liquidez conforme os critérios de classificação.", "passos": ["O enunciado descreve bens ou direitos de curto prazo e elevada liquidez.", "Isso corresponde ao conceito de ativo circulante.", "Logo, alternativa E."], "calculo": "Não há cálculo.", "correta": "E — Ativo circulante.", "erradas": ["A) Passivo circulante representa obrigações de curto prazo.", "B) PL representa a participação residual dos proprietários.", "C) Passivo permanente não é o conceito descrito.", "D) Ativo permanente é terminologia incompatível com a descrição dada."], "fundamento": "Classificação do ativo no Balanço Patrimonial segundo a legislação societária e normas contábeis aplicáveis.", "pegadinha": "“Curto prazo” e “liquidez” são pistas diretas para ativo circulante.", "cobranca": "Contabilidade Geral - Balanço Patrimonial"}'::jsonb WHERE id='3025523';
UPDATE questoes SET resolution='{"regra": "Custo histórico registra o ativo pelo custo da aquisição/incorrência; valor justo é o preço de saída em transação ordenada entre participantes do mercado na data de mensuração; valor em uso usa fluxos de caixa futuros descontados; custo corrente reflete o custo de adquirir/produzir ativo equivalente na data da mensuração.", "passos": ["1) A alternativa D descreve preço que seria recebido numa transação entre participantes do mercado na data de mensuração.", "2) Essa é a definição de valor justo.", "3) As demais alternativas atribuem conceitos diferentes às bases descritas."], "calculo": "Não há cálculo.", "correta": "D — valor justo.", "erradas": ["A: custo de aquisição corresponde ao custo histórico, não ao custo corrente, e a descrição ainda mistura ajuste de mercado.", "B: preço de venda atual não é custo histórico.", "C: fluxos de caixa futuros descontados relacionam-se ao valor em uso, não ao custo corrente.", "E: variações de mercado descaracterizam a descrição como simples custo histórico."], "fundamento": "NBC TG Estrutura Conceitual para Relatório Financeiro — bases de mensuração.", "pegadinha": "Diferencie preço de entrada/custo de aquisição de preço de saída/valor justo e de valor presente dos fluxos de caixa/valor em uso.", "cobranca": "Definições das bases de mensuração."}'::jsonb WHERE id='3435103';
UPDATE questoes SET resolution='{"regra": "Relevância possui valor preditivo e/ou confirmatório; representação fidedigna busca completude, neutralidade e ausência de erro; tempestividade é característica de melhoria e envolve disponibilização em tempo hábil; comparabilidade não exige uniformidade; verificabilidade permite que observadores qualificados cheguem a consenso, não necessariamente identidade absoluta.", "passos": ["1) Relevância → V.", "2) Representação fidedigna → V.", "3) A afirmação sobre tempestividade como “fundamental” e sem relação com valor preditivo é F: tempestividade é característica qualitativa de melhoria.", "4) Comparabilidade sem exigir uniformidade → V.", "5) Verificabilidade → V."], "calculo": "Sequência: V, V, F, V, V.", "correta": "A — V, V, F, V, V.", "erradas": ["B, C e D apresentam sequências incompatíveis com a classificação das características qualitativas."], "fundamento": "NBC TG Estrutura Conceitual para Relatório Financeiro — características qualitativas da informação financeira útil.", "pegadinha": "A banca troca características fundamentais (relevância e representação fidedigna) por características de melhoria (comparabilidade, verificabilidade, tempestividade e compreensibilidade).", "cobranca": "V/F sobre características qualitativas."}'::jsonb WHERE id='3597756';
UPDATE questoes SET resolution='{"regra": "Ativos, passivos e patrimônio líquido são elementos relacionados à posição financeira; receitas e despesas são elementos relacionados ao desempenho financeiro. Empréstimo recebido aumenta passivo e ativo, mas não constitui receita.", "passos": ["1) I é verdadeira.", "2) II é verdadeira.", "3) III é verdadeira: uma redução de ativo que não seja distribuição aos sócios pode representar despesa, quando atender ao conceito.", "4) IV é falsa: empréstimo é transação de financiamento, não receita."], "calculo": "Não há cálculo.", "correta": "A — I, II e III, apenas.", "erradas": ["B inclui IV e exclui I e II.", "C considera IV verdadeira.", "D exclui III, que está correta no contexto conceitual."], "fundamento": "NBC TG Estrutura Conceitual para Relatório Financeiro — elementos das demonstrações contábeis.", "pegadinha": "Entrada de dinheiro não significa receita: empréstimo aumenta caixa e passivo.", "cobranca": "Classificação conceitual de elementos patrimoniais e de desempenho."}'::jsonb WHERE id='3598367';
UPDATE questoes SET resolution='{"regra": "Comparabilidade não exige uniformidade; tempestividade é disponibilização em tempo hábil; verificação direta pode envolver observação ou reexecução; complexidade não deve ser simplesmente excluída se isso prejudicar a completude.", "passos": ["1) Uniformidade obrigatória entre fenômenos diferentes → F.", "2) Tempestividade em tempo hábil → V.", "3) Reexecução de cálculos é exemplo de verificação direta → F, pois a afirmação apresenta o procedimento como se fosse necessariamente “direto”; a classificação da questão conduz a F.", "4) Excluir fenômenos complexos sacrificando completude → F."], "calculo": "Sequência: F, V, F, F.", "correta": "C — F, V, F, F.", "erradas": ["A considera a quarta verdadeira.", "B considera tempestividade falsa e verificação direta verdadeira.", "D considera comparabilidade verdadeira."], "fundamento": "NBC TG Estrutura Conceitual — características qualitativas de melhoria, especialmente comparabilidade, verificabilidade e tempestividade.", "pegadinha": "A questão mistura verificabilidade direta e indireta; não confunda “reexecução” com uma regra que torne qualquer reexecução automaticamente verificação direta no sentido da afirmação.", "cobranca": "V/F sobre características qualitativas e verificabilidade."}'::jsonb WHERE id='3598371';
UPDATE questoes SET resolution='{"regra": "Na Estrutura Conceitual, ativo é um recurso econômico presente controlado pela entidade como resultado de eventos passados.", "passos": ["1) Identificar a definição normativa.", "2) O recurso econômico é presente.", "3) O controle decorre de eventos passados."], "calculo": "Não há cálculo.", "correta": "B — presente, passados.", "erradas": ["A usa eventos futuros.", "C e D trocam a natureza temporal do recurso/evento."], "fundamento": "NBC TG Estrutura Conceitual para Relatório Financeiro — definição de ativo.", "pegadinha": "O ativo não é “resultado de eventos futuros”; a condição atual decorre de eventos passados.", "cobranca": "Preenchimento literal da definição de ativo."}'::jsonb WHERE id='3598375';
UPDATE questoes SET resolution='{"regra": "Materialidade é um aspecto da relevância e depende da natureza ou magnitude, ou de ambas, no contexto específico da entidade; não existe percentual fixo universal previamente estabelecido pela norma.", "passos": ["1) A, B, C e D são compatíveis com a Estrutura Conceitual.", "2) E afirma que materialidade pode ser definida por percentual fixo do ativo total previamente estabelecido em norma.", "3) Essa generalização é incorreta."], "calculo": "Não há cálculo.", "correta": "E — é a alternativa incorreta.", "erradas": ["A: correta, estimativas não eliminam utilidade se adequadamente divulgadas.", "B: correta, relevância possui valor preditivo e/ou confirmatório.", "C: compatível com prudência contribuindo para neutralidade.", "D: correta quanto à representação fidedigna."], "fundamento": "NBC TG Estrutura Conceitual para Relatório Financeiro — relevância, materialidade e representação fidedigna.", "pegadinha": "Não memorize um percentual fixo para materialidade como se fosse regra geral da Estrutura Conceitual.", "cobranca": "Identificação da afirmação incorreta sobre características qualitativas."}'::jsonb WHERE id='3930598';
UPDATE questoes SET resolution='{"regra": "Capitais de terceiros = Passivo Exigível. Ativo Total = 1,5 × Passivo Exigível. Ativo Circulante = 30% do Ativo Total, então o Ativo Não Circulante é 70% do Ativo Total. Passivo Circulante é 25% dos capitais de terceiros.", "passos": ["1) Passivo Exigível = R$ 1.400.000,00.", "2) Ativo Total = 1,5 × 1.400.000 = R$ 2.100.000,00.", "3) Ativo realizável até 31/12/2023 = 30% × 2.100.000 = R$ 630.000,00, tratado na questão como parcela realizável no curto prazo.", "4) Ativo Não Circulante = 2.100.000 − 630.000 = R$ 1.470.000,00.", "5) Passivo Circulante = 25% × 1.400.000 = R$ 350.000,00."], "calculo": "AT = 1,5 × 1.400.000 = 2.100.000; ANC = 70% × 2.100.000 = 1.470.000; PC = 25% × 1.400.000 = 350.000.", "correta": "C — R$ 1.470.000,00 e R$ 350.000,00.", "erradas": ["A e E apresentam valores incompatíveis com os percentuais.", "B e D erram pelo menos um dos dois valores."], "fundamento": "Lei nº 6.404/1976, classificação do balanço patrimonial; cálculo pela equação e pelos percentuais fornecidos no enunciado.", "pegadinha": "Primeiro encontre o Ativo Total usando a relação com o Passivo Exigível; depois aplique os percentuais. Não confunda 30% do ativo total com 30% do passivo.", "cobranca": "Cálculo de classificação patrimonial a partir de percentuais."}'::jsonb WHERE id='2715254';
UPDATE questoes SET resolution='{"regra": "Patrimônio Líquido = Ativo Total − Passivo Exigível.", "passos": ["1) Passivo Exigível = R$ 1.400.000,00.", "2) Ativo Total = 1,5 × 1.400.000 = R$ 2.100.000,00.", "3) PL = 2.100.000 − 1.400.000 = R$ 700.000,00."], "calculo": "PL = AT − PE = 2.100.000 − 1.400.000 = R$ 700.000,00.", "correta": "C — R$ 700.000,00.", "erradas": ["A, B, D e E não correspondem à diferença entre ativo total e passivo exigível calculados a partir do enunciado."], "fundamento": "Equação patrimonial: Ativo = Passivo + Patrimônio Líquido.", "pegadinha": "A informação sobre receita e lucro não é necessária para este cálculo específico.", "cobranca": "Equação patrimonial aplicada a dados percentuais."}'::jsonb WHERE id='2715262';
UPDATE questoes SET resolution='{"regra": "No ativo, as contas são dispostas em ordem decrescente de grau de liquidez.", "passos": ["1) A questão pede o grupo do balanço cuja ordem segue a liquidez.", "2) O ativo é organizado de acordo com o grau de liquidez dos elementos.", "3) A ordem é decrescente: itens mais líquidos aparecem antes dos menos líquidos."], "calculo": "Não há cálculo.", "correta": "C — ativo / decrescente.", "erradas": ["A erra a ordem.", "B e D deslocam a regra para o passivo.", "E usa uma ordem que não corresponde à lei."], "fundamento": "Lei nº 6.404/1976, art. 178 e estrutura/classificação do balanço patrimonial.", "pegadinha": "Liquidez é característica usada para ordenar o ativo; no passivo, a classificação segue a natureza e exigibilidade das obrigações.", "cobranca": "Literalidade da Lei das Sociedades por Ações sobre classificação do balanço."}'::jsonb WHERE id='2715288';
UPDATE questoes SET resolution='{"regra": "Ativo Não Circulante = Ativo Total − parcela realizável no curso do exercício seguinte.", "passos": ["1) Ativo Total = R$ 1.750.000,00.", "2) 1/5 é realizável no exercício seguinte: 1.750.000 ÷ 5 = R$ 350.000,00.", "3) Ativo Não Circulante = 1.750.000 − 350.000 = R$ 1.400.000,00."], "calculo": "ANC = 1.750.000 − (1/5 × 1.750.000) = 1.750.000 − 350.000 = R$ 1.400.000,00.", "correta": "E — R$ 1.400.000,00.", "erradas": ["A, B, C e D não resultam da subtração da parcela de curto prazo indicada no enunciado."], "fundamento": "Lei nº 6.404/1976, classificação entre ativo circulante e não circulante, conforme prazo de realização.", "pegadinha": "O dado sobre capitais de terceiros não é necessário para determinar o ANC nesta questão.", "cobranca": "Cálculo direto de ativo não circulante."}'::jsonb WHERE id='3680300';
UPDATE questoes SET resolution='{"regra": "Patrimônio Líquido = Ativo Total − Capitais de Terceiros (Passivo Exigível).", "passos": ["1) Ativo Total = R$ 1.750.000,00.", "2) Capitais de terceiros = 3/4 × 1.750.000 = R$ 1.312.500,00.", "3) PL = 1.750.000 − 1.312.500 = R$ 437.500,00.", "4) O percentual de 55% exigível após um ano é irrelevante para o cálculo do PL."], "calculo": "Capitais de terceiros = 75% × 1.750.000 = 1.312.500; PL = 1.750.000 − 1.312.500 = R$ 437.500,00.", "correta": "C — R$ 437.500,00.", "erradas": ["A e E não respeitam a equação patrimonial.", "B e D não correspondem a 25% do ativo total, que é a parcela do PL neste enunciado."], "fundamento": "Equação patrimonial: Ativo = Passivo Exigível + Patrimônio Líquido.", "pegadinha": "Os 55% exigíveis após um ano servem para classificar o passivo, mas não alteram o valor total dos capitais de terceiros nem o PL.", "cobranca": "Equação patrimonial e identificação de dados irrelevantes para o cálculo."}'::jsonb WHERE id='3680304';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — identificação dos grandes grupos.", "regra": "No Balanço Patrimonial, Caixa, Duplicatas a Receber e Estoques são ativos; Duplicatas a Pagar representa obrigação e, portanto, integra o Passivo.", "passos": ["1) Caixa representa disponibilidade da entidade: Ativo.", "2) Duplicatas a Receber representam direito contra terceiros: Ativo.", "3) Duplicatas a Pagar representam obrigação perante terceiros: Passivo.", "4) Estoques representam recursos controlados destinados às atividades da entidade: Ativo."], "calculo": "Não há cálculo.", "correta": "C — Ativo; Ativo; Passivo e Ativo.", "erradas": ["A) classifica Duplicatas a Pagar como Ativo.", "B) não apresenta classificação.", "D) classifica Duplicatas a Receber como Passivo e Estoque como Passivo.", "E) classifica Duplicatas a Receber como Passivo e Duplicatas a Pagar como Ativo."], "fundamento": "Estrutura patrimonial básica: ativos representam recursos/direitos controlados; passivos representam obrigações.", "pegadinha": "“Receber” indica direito (ativo), enquanto “pagar” indica obrigação (passivo)."}'::jsonb WHERE id='2158747';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — classificação em circulante e não circulante.", "regra": "Caixa e Estoques são Ativo Circulante. Direito a receber em até 365 dias, no contexto apresentado, é Ativo Circulante. Obrigação com vencimento superior a 365 dias é Passivo Não Circulante.", "passos": ["1) Caixa: disponibilidade de curto prazo → Ativo Circulante.", "2) Duplicata a receber em até 365 dias → Ativo Circulante.", "3) Duplicata a pagar com vencimento superior a 365 dias → Passivo Não Circulante.", "4) Estoque → Ativo Circulante."], "calculo": "Não há cálculo. A classificação depende do prazo e da natureza da conta.", "correta": "E — Ativo Circulante; Ativo Circulante; Passivo não circulante; Ativo Circulante.", "erradas": ["A) classifica o direito de curto prazo como Ativo Não Circulante.", "B) não fornece classificação.", "C) classifica a obrigação de longo prazo como Passivo Circulante.", "D) classifica Caixa como Ativo Não Circulante."], "fundamento": "Classificação patrimonial segundo a natureza do elemento e o prazo de realização/exigibilidade.", "pegadinha": "O prazo de “mais de 365 dias” é o dado decisivo para a classificação da duplicata a pagar como não circulante."}'::jsonb WHERE id='2158748';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — recursos próprios e recursos de terceiros.", "regra": "Recursos de terceiros correspondem às obrigações da entidade perante terceiros, como fornecedores, funcionários e instituições financeiras. Recursos próprios correspondem ao Patrimônio Líquido.", "passos": ["1) “Recursos de terceiros” devem ser procurados nas obrigações da entidade.", "2) Fornecedores, funcionários e empréstimos são exemplos de obrigações.", "3) Portanto, a descrição da alternativa C corresponde a recursos de terceiros.", "4) As demais alternativas confundem recursos próprios com disponibilidades ou tratam capital dos sócios como recurso de terceiros."], "calculo": "Não há cálculo.", "correta": "C — Os recursos de terceiros são as obrigações contraídas com fornecedores, funcionários e empréstimos, entre outros.", "erradas": ["A) disponibilidades não formam exclusivamente os recursos próprios; caixa é ativo.", "B) capital investido pelos sócios integra recursos próprios/Patrimônio Líquido.", "D) fornecedores, funcionários e empréstimos são recursos de terceiros, não próprios.", "E) dinheiro em caixa é ativo, não a definição de recursos próprios."], "fundamento": "Equação patrimonial: Ativo = Passivo Exigível + Patrimônio Líquido; o passivo exigível representa capitais de terceiros e o PL, recursos próprios.", "pegadinha": "A questão pergunta pela origem dos recursos, não pela localização física do dinheiro. Caixa é ativo, independentemente de a origem dos recursos ser própria ou de terceiros."}'::jsonb WHERE id='2431111';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — conceito de Ativo.", "regra": "Na abordagem introdutória utilizada pela questão, o Ativo é formado pelos bens e direitos da entidade.", "passos": ["1) Bens representam recursos controlados pela entidade.", "2) Direitos representam valores a receber de terceiros.", "3) Ambos compõem o Ativo.", "4) Obrigações pertencem ao Passivo, e Patrimônio Líquido não é Ativo."], "calculo": "Não há cálculo.", "correta": "A — Bens e direitos.", "erradas": ["B) Patrimônio Líquido não é componente do Ativo.", "C) a alternativa declara que nenhuma está correta, mas A está correta.", "D) obrigações são Passivo, não Ativo."], "fundamento": "Conceito básico de estrutura patrimonial: Ativo reúne bens e direitos; Passivo reúne obrigações; PL representa os recursos próprios.", "pegadinha": "Não confundir patrimônio líquido com patrimônio/ativo. O PL é a participação residual nos ativos após dedução dos passivos."}'::jsonb WHERE id='2153843';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — subgrupo das disponibilidades.", "regra": "Dinheiro mantido em caixa é uma disponibilidade e, no Ativo Circulante, integra o subgrupo de disponibilidades.", "passos": ["1) A conta representa dinheiro disponível imediatamente.", "2) Dinheiro em caixa não é estoque nem provisão.", "3) Na estrutura apresentada pela questão, sua classificação é Disponibilidades."], "calculo": "Não há cálculo.", "correta": "B — Disponibilidades.", "erradas": ["A) Bancos é uma conta/forma específica de disponibilidade, mas não é o subgrupo solicitado na classificação da questão.", "C) Estoque representa bens destinados à venda/consumo, não dinheiro em caixa.", "D) Provisões não representam o dinheiro disponível em caixa."], "fundamento": "Classificação do Ativo Circulante: disponibilidades abrangem caixa e equivalentes de caixa conforme a estrutura contábil aplicável.", "pegadinha": "A banca usa “Bancos” como alternativa para induzir a tratar uma conta específica como se fosse o subgrupo."}'::jsonb WHERE id='2153844';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — classificação de direito realizável no curto prazo.", "regra": "Duplicata a receber com vencimento em 30 dias é direito de curto prazo e, portanto, integra o Ativo Circulante.", "passos": ["1) Duplicata a receber representa um direito.", "2) O prazo informado é de 30 dias, portanto curto prazo.", "3) Direito de curto prazo → Ativo Circulante."], "calculo": "Não há cálculo.", "correta": "C — Ativo Circulante.", "erradas": ["A) Passivo Circulante representa obrigações, não direitos a receber.", "B) há alternativa correta, portanto não é o caso de “nenhuma”.", "D) Ativo Não Circulante seria incompatível com o prazo de 30 dias."], "fundamento": "Classificação dos direitos segundo o prazo de realização: direitos realizáveis no curto prazo integram o Ativo Circulante.", "pegadinha": "O termo “duplicata” não determina sozinho a classificação; o prazo de vencimento é o dado decisivo aqui."}'::jsonb WHERE id='2153845';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Ativo Total.", "regra": "Ativo Total é a soma dos itens classificados no Ativo: disponibilidades, direitos a curto e longo prazo e imobilizado. Obrigações como salários e dívidas não entram no Ativo.", "passos": ["1) Disponibilidades = R$ 100.000,00.", "2) Recebimentos a curto prazo = R$ 100.000,00.", "3) Recebimento a longo prazo = R$ 800.000,00.", "4) Imobilizado = R$ 1.000.000,00.", "5) Somando os ativos: 100.000 + 100.000 + 800.000 + 1.000.000 = 2.000.000.", "6) Salários a pagar e dívidas de curto/longo prazo são passivos e não entram no Ativo Total."], "calculo": "Ativo Total = 100.000 + 100.000 + 800.000 + 1.000.000 = R$ 2.000.000,00.", "correta": "E — R$ 2.000.000,00.", "erradas": ["A) R$ 1.800.000,00: não corresponde à soma de todos os itens do ativo.", "B) R$ 1.000.000,00: considera apenas o imobilizado.", "C) R$ 1.500.000,00: deixa de considerar parte dos direitos/disponibilidades.", "D) R$ 0,00: ignora os ativos apresentados."], "fundamento": "O Ativo Total corresponde à soma dos ativos reconhecidos no Balanço Patrimonial; passivos não são subtraídos para obter o total do ativo.", "pegadinha": "Os valores de salários a pagar e dívidas são fornecidos para testar se o candidato os inclui indevidamente na soma ou confunde Ativo Total com Patrimônio Líquido."}'::jsonb WHERE id='1119805';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — equação patrimonial para encontrar o Imobilizado.", "regra": "No Balanço Patrimonial, Ativo = Passivo + Patrimônio Líquido. O Ativo informado é composto por Ativo Circulante, Ativo Realizável a Longo Prazo e Imobilizado.", "passos": ["1) Some o Passivo Circulante e o Passivo Não Circulante: 500.000 + 500.000 = 1.000.000.", "2) Some o Patrimônio Líquido: 1.000.000 + 900.000 = 1.900.000.", "3) Portanto, o Ativo Total deve ser R$ 1.900.000,00.", "4) O Ativo já conhecido, sem o imobilizado, é 200.000 + 800.000 = R$ 1.000.000,00.", "5) Imobilizado = 1.900.000 − 1.000.000 = R$ 900.000,00."], "calculo": "Ativo Total = 500.000 + 500.000 + 900.000 = R$ 1.900.000,00.\nImobilizado = 1.900.000 − 200.000 − 800.000 = R$ 900.000,00.", "correta": "E — R$ 900.000,00.", "erradas": ["A) R$ 100.000,00: não corresponde à diferença entre Ativo Total e os demais ativos.", "B) R$ 50.000,00: não decorre da equação patrimonial.", "C) R$ 1.000.000,00: corresponde ao Ativo já conhecido (AC + ARLP), não ao imobilizado.", "D) R$ 800.000,00: corresponde ao Ativo Realizável a Longo Prazo, não ao imobilizado."], "fundamento": "Equação patrimonial: Ativo = Passivo + Patrimônio Líquido.", "pegadinha": "A questão fornece simultaneamente grupos do Ativo e do Passivo/PL. A armadilha é somar apenas os ativos conhecidos e esquecer que o total do Ativo deve fechar com Passivo + PL."}'::jsonb WHERE id='1119806';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial e DRE — julgamento de afirmativas.", "regra": "A DRE evidencia a formação do resultado; o Balanço Patrimonial evidencia a posição patrimonial. Em uma empresa industrial, os estoques percorrem matérias-primas → produtos em elaboração → produtos acabados; somente quando vendidos o custo correspondente compõe o CMV.", "passos": ["1) I é verdadeira: a DRE apresenta de forma vertical a composição do resultado.", "2) II é verdadeira: a descrição de bens, direitos e obrigações corresponde, em linguagem tradicional, aos elementos evidenciados no BP.", "3) III é falsa: comprar mercadorias não significa, por si só, reconhecer CMV; o custo é apropriado quando ocorre a venda.", "4) IV é falsa: produtos acabados não são “incorporados ao CMV aguardando vendas”; o CMV está associado às mercadorias/produtos vendidos.", "5) V é verdadeira: duplicatas a receber normalmente surgem de venda a prazo.", "6) Sequência: V, V, F, F, V."], "calculo": "Não há cálculo.", "correta": "A — V, V, F, F, V.", "erradas": ["B) Torna a primeira afirmativa falsa, embora ela esteja correta.", "C) Considera falsas II e V e verdadeiras III e IV, contrariando os conceitos apresentados.", "D) Considera IV verdadeira, mas a afirmativa IV está incorreta.", "E) Considera I falsa e III verdadeira, invertendo pontos centrais da questão."], "fundamento": "Conteúdo conceitual de BP, DRE, estoques e CMV.", "pegadinha": "A pegadinha está principalmente em “aguardando a vendas”: estoque de produto acabado ainda não vendido não é CMV. O custo vai ao resultado quando relacionado à venda."}'::jsonb WHERE id='916299';
UPDATE questoes SET resolution='{"cobranca": "Classificação de terreno — Ativo Não Circulante / Investimentos.", "regra": "Na Lei 6.404/1976, são classificados em Investimentos os direitos de qualquer natureza não classificáveis no ativo circulante e que não se destinem à manutenção da atividade da companhia. Terreno mantido para valorização/venda futura, sem destinação à atividade operacional, enquadra-se no subgrupo Investimentos segundo o critério cobrado.", "passos": ["1) O terreno não é destinado à manutenção da atividade da companhia.", "2) A questão informa intenção de permanência para venda futura.", "3) Entre as alternativas, a classificação patrimonial apresentada para esse terreno é Investimentos no Ativo Não Circulante.", "4) Portanto, a alternativa D corresponde ao enquadramento indicado pelo caderno."], "calculo": "Não há cálculo.", "correta": "D — No Balanço Patrimonial, no Ativo Não Circulante, subgrupo Investimentos.", "erradas": ["A) Imobilizado: não é a classificação indicada quando o bem não se destina à manutenção das atividades da companhia.", "B) DRE: demonstração de resultado não é o local de apresentação do terreno.", "C) Notas Explicativas: notas podem complementar informações, mas não substituem a classificação no BP.", "E) DFC: a demonstração dos fluxos de caixa não é o local de classificação do ativo."], "fundamento": "Lei 6.404/1976, art. 179, III — classificação de Investimentos.", "pegadinha": "A expressão decisiva é “não destinado à manutenção da atividade da companhia”. Isso afasta o Imobilizado."}'::jsonb WHERE id='916306';
UPDATE questoes SET resolution='{"cobranca": "Lei 6.404/1976 — critérios de avaliação do Passivo.", "regra": "As obrigações em moeda estrangeira, com cláusula de paridade cambial, devem ser convertidas em moeda nacional à taxa de câmbio em vigor na data do balanço.", "passos": ["1) A questão pede a alternativa de acordo com a Lei 6.404/1976.", "2) A regra específica para obrigações em moeda estrangeira é a conversão para moeda nacional pela taxa vigente na data do balanço.", "3) A alternativa A reproduz essa regra.", "4) As demais alternativas alteram o critério legal ou deixam de converter a obrigação para moeda nacional."], "calculo": "Não há cálculo.", "correta": "A — As obrigações em moeda estrangeira, com cláusula de paridade cambial, serão convertidas em moeda nacional à taxa de câmbio em vigor na data do balanço.", "erradas": ["B) Fala em “valor de aquisição” para obrigações, critério que não corresponde à regra específica cobrada.", "C) Generaliza valor justo para os passivos, o que não corresponde ao dispositivo apresentado.", "D) Mantém a obrigação em moeda estrangeira, contrariando a conversão para moeda nacional."], "fundamento": "Lei 6.404/1976, art. 184, I.", "pegadinha": "A pegadinha é trocar “taxa de câmbio na data do balanço” por valor histórico, valor de aquisição ou simples divulgação em moeda estrangeira."}'::jsonb WHERE id='1058693';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo de Ativo Circulante e Ativo Não Circulante.", "regra": "Ativo Circulante reúne disponibilidades, direitos realizáveis no curso do ciclo operacional ou até o término do exercício seguinte, conforme o critério aplicável. O Ativo Não Circulante inclui os direitos de longo prazo e o imobilizado, entre outros grupos.", "passos": ["1) Ativo Circulante: disponibilidades 500.000 + duplicatas até 365 dias 30.000 + estoque 200.000 = 730.000.", "2) Ativo Não Circulante: duplicatas a receber após 365 dias 100.000 + imobilizado 350.000 = 450.000.", "3) Os valores de salários, duplicatas e empréstimos a pagar são passivos e não entram nessa soma."], "calculo": "AC = 500.000 + 30.000 + 200.000 = R$ 730.000,00.\nANC = 100.000 + 350.000 = R$ 450.000,00.", "correta": "D — R$ 730.000,00 e R$ 450.000,00.", "erradas": ["A) Inclui valores de passivo ou classifica incorretamente os grupos.", "B) Subestima o Ativo Circulante e o Não Circulante.", "C) Considera apenas parte dos direitos e não fecha com os dados apresentados."], "fundamento": "Classificação do Ativo no Balanço Patrimonial.", "pegadinha": "A pegadinha é separar os itens pelo prazo e pela natureza: contas a pagar e empréstimos são passivos, mesmo quando aparecem na mesma lista de valores."}'::jsonb WHERE id='1273138';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Passivo Circulante e Não Circulante.", "regra": "Passivo Circulante contém obrigações exigíveis no curto prazo; Passivo Não Circulante contém obrigações exigíveis após o prazo de curto prazo indicado no enunciado.", "passos": ["1) Passivo Circulante: salários e encargos 50.000 + duplicatas a pagar 20.000 + empréstimos a pagar até 365 dias 250.000.", "2) Total do Passivo Circulante = 320.000.", "3) Passivo Não Circulante: empréstimos a pagar após 365 dias = 100.000."], "calculo": "PC = 50.000 + 20.000 + 250.000 = R$ 320.000,00.\nPNC = R$ 100.000,00.", "correta": "C — R$ 320.000,00 e R$ 100.000,00.", "erradas": ["A) R$ 1.180.000 e R$ 760.000: são valores incompatíveis com a soma das obrigações apresentadas.", "B) R$ 730.000 e R$ 320.000: mistura valores do Ativo com o Passivo.", "D) R$ 730.000 e R$ 450.000: corresponde aos valores calculados para AC e ANC da questão anterior."], "fundamento": "Classificação do Passivo no Balanço Patrimonial.", "pegadinha": "A questão é praticamente uma continuação da 66. O prazo indicado na própria descrição determina a classificação."}'::jsonb WHERE id='1273142';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — Passivo Total e Patrimônio Líquido.", "regra": "Passivo Total = Passivo Circulante + Passivo Não Circulante. Depois, pela equação patrimonial, Patrimônio Líquido = Ativo Total − Passivo Total.", "passos": ["1) Da questão anterior: PC = 320.000 e PNC = 100.000.", "2) Passivo Total = 320.000 + 100.000 = 420.000.", "3) Ativo Total = AC 730.000 + ANC 450.000 = 1.180.000.", "4) PL = 1.180.000 − 420.000 = 760.000."], "calculo": "Passivo Total = 320.000 + 100.000 = R$ 420.000,00.\nPL = 1.180.000 − 420.000 = R$ 760.000,00.", "correta": "A — R$ 1.180.000,00 e R$ 760.000,00.", "erradas": ["B) R$ 730.000 e R$ 320.000: são, respectivamente, AC e PC.", "C) R$ 320.000 e R$ 100.000: são PC e PNC.", "D) R$ 730.000 e R$ 450.000: são AC e ANC."], "fundamento": "Equação patrimonial: Ativo = Passivo + Patrimônio Líquido.", "pegadinha": "A série de questões reutiliza os mesmos dados. A armadilha é não perceber que cada questão muda apenas o que deve ser calculado."}'::jsonb WHERE id='1273144';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Ativo Circulante.", "regra": "No conjunto de dados, disponibilidades e duplicatas a receber até 365 dias compõem o Ativo Circulante. O direito a receber após 365 dias e o capital imobilizado pertencem ao Ativo Não Circulante.", "passos": ["1) Disponibilidades = 50.000.", "2) Duplicatas a receber até 365 dias = 20.000.", "3) Somar apenas esses itens: 50.000 + 20.000 = 70.000.", "4) A duplicata após 365 dias e o capital imobilizado não entram no AC."], "calculo": "AC = 50.000 + 20.000 = R$ 70.000,00.", "correta": "A — R$ 70.000,00.", "erradas": ["B) R$ 75.000: não corresponde à soma dos itens circulantes.", "C) R$ 80.000: inclui valor que não pertence ao AC.", "D) R$ 85.000: também não decorre dos dados."], "fundamento": "Classificação dos elementos do Ativo por prazo/natureza.", "pegadinha": "A palavra “até 365 dias” é o marcador de curto prazo. A duplicata “mais de 365 dias” não deve ser somada ao AC."}'::jsonb WHERE id='2026594';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Ativo Não Circulante.", "regra": "No conjunto apresentado, a duplicata a receber em prazo superior a 365 dias é realizável a longo prazo e o capital imobilizado integra o Ativo Não Circulante.", "passos": ["1) Duplicatas a receber após 365 dias = 40.000.", "2) Capital imobilizado = 500.000.", "3) Somando os itens do ANC: 40.000 + 500.000 = 540.000."], "calculo": "ANC = 40.000 + 500.000 = R$ 540.000,00.", "correta": "C — R$ 540.000,00.", "erradas": ["A) R$ 387.000: não corresponde à soma dos elementos não circulantes.", "B) R$ 490.000: não considera corretamente os dois itens.", "D) R$ 580.000: soma valor que não pertence ao ANC."], "fundamento": "Classificação dos elementos do Ativo Não Circulante.", "pegadinha": "A expressão “mais de 365 dias” deve ser separada das disponibilidades e dos recebíveis de curto prazo."}'::jsonb WHERE id='2026596';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Ativo Total.", "regra": "Ativo Total é a soma do Ativo Circulante com o Ativo Não Circulante.", "passos": ["1) Da questão 69, AC = 70.000.", "2) Da questão 70, ANC = 540.000.", "3) Ativo Total = 70.000 + 540.000 = 610.000."], "calculo": "Ativo Total = 70.000 + 540.000 = R$ 610.000,00.", "correta": "D — R$ 610.000,00.", "erradas": ["A) R$ 356.000: não corresponde à soma dos grupos do ativo.", "B) R$ 478.000: não corresponde aos dados.", "C) R$ 570.000: fica R$ 40.000 abaixo do total correto, justamente o recebível de longo prazo."], "fundamento": "Composição do Ativo Total no Balanço Patrimonial.", "pegadinha": "A questão exige aproveitar os resultados anteriores. O recebível de longo prazo não pode ser esquecido ao formar o Ativo Total."}'::jsonb WHERE id='2026598';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Passivo Circulante.", "regra": "O Passivo Circulante é formado, nos dados fornecidos, por salários e encargos a pagar de curto prazo. Não há outra obrigação de curto prazo indicada.", "passos": ["1) A única obrigação explicitamente apresentada é salários e encargos a pagar = 100.000.", "2) Como não há outra dívida de curto prazo indicada no enunciado, o Passivo Circulante é 100.000."], "calculo": "Passivo Circulante = R$ 100.000,00.", "correta": "B — R$ 100.000,00.", "erradas": ["A) R$ 90.000: não corresponde ao valor da obrigação apresentada.", "C) R$ 200.000: dobra indevidamente a obrigação.", "D) R$ 300.000: também inclui valores que não são passivos circulantes."], "fundamento": "Classificação e mensuração dos elementos do Passivo.", "pegadinha": "A lista contém vários valores do Ativo. A armadilha é transformar direitos/ativos em obrigações."}'::jsonb WHERE id='2026601';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Passivo Não Circulante.", "regra": "Passivo Não Circulante depende da existência de obrigações exigíveis após o curto prazo. No conjunto de dados desta série, não foi indicada nenhuma obrigação de longo prazo.", "passos": ["1) O enunciado apresenta salários e encargos a pagar, mas não informa outra dívida de longo prazo.", "2) Portanto, dentro dos dados fornecidos, não existe valor de Passivo Não Circulante.", "3) O resultado é zero."], "calculo": "Passivo Não Circulante = R$ 0,00.", "correta": "D — R$ 0,00.", "erradas": ["A) R$ 12.000: não é informado como obrigação de longo prazo.", "B) R$ 15.600: não deriva dos dados.", "C) R$ 13.000: também não deriva dos dados."], "fundamento": "Classificação do Passivo por exigibilidade.", "pegadinha": "Não confundir “duplicatas a receber mais de 365 dias” com dívida de longo prazo: é um direito da empresa, portanto pertence ao Ativo."}'::jsonb WHERE id='2026603';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — soma das dívidas.", "regra": "No conjunto da questão, a dívida indicada é o valor de salários e encargos a pagar. Direitos a receber e capital imobilizado não são dívidas.", "passos": ["1) Identifique o único passivo informado: salários e encargos a pagar = 100.000.", "2) Os demais valores são disponibilidades, direitos a receber e capital imobilizado.", "3) Portanto, a soma das dívidas é 100.000."], "calculo": "Dívidas somadas = R$ 100.000,00.", "correta": "D — R$ 100.000,00.", "erradas": ["A) R$ 70.000: corresponde a uma soma de ativos da série.", "B) R$ 80.000: não corresponde ao passivo informado.", "C) R$ 90.000: não corresponde ao passivo informado."], "fundamento": "Identificação de Passivos no Balanço Patrimonial.", "pegadinha": "A pegadinha é reconhecer que “duplicatas a receber” são direitos, não dívidas da empresa."}'::jsonb WHERE id='2026605';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Patrimônio Líquido.", "regra": "Pela equação patrimonial, PL = Ativo Total − Passivo Total.", "passos": ["1) Da questão 71, Ativo Total = 610.000.", "2) Da questão 72, Passivo Circulante = 100.000.", "3) Da questão 73, Passivo Não Circulante = 0.", "4) Passivo Total = 100.000.", "5) PL = 610.000 − 100.000 = 510.000."], "calculo": "PL = Ativo Total − Passivo Total = 610.000 − 100.000 = R$ 510.000,00.", "correta": "A — R$ 510.000,00.", "erradas": ["B) R$ 520.000: não fecha a equação patrimonial.", "C) R$ 530.000: não fecha a equação patrimonial.", "D) R$ 540.000: corresponde ao ANC da questão 70, não ao PL."], "fundamento": "Equação patrimonial: Ativo = Passivo + Patrimônio Líquido.", "pegadinha": "A série testa a capacidade de transportar resultados de uma questão para outra. Aqui, o PL é o valor residual após a dedução do Passivo Total."}'::jsonb WHERE id='2026607';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — conceito de ativo circulante.", "regra": "O ativo circulante compreende disponibilidades, direitos realizáveis no curso do exercício social subsequente e aplicações de recursos em despesas do exercício seguinte.", "passos": ["1) Identifique o grupo: ativo circulante.", "2) Considere disponibilidades e direitos realizáveis no ciclo/exercício subsequente.", "3) Inclua também despesas antecipadas/aplicações de recursos referentes ao exercício seguinte."], "calculo": "Não há cálculo; os valores de 2014 e 2015 apenas contextualizam a pergunta.", "correta": "C — disponibilidades, direitos realizáveis no curso do exercício social subsequente e aplicações de recursos em despesas do exercício seguinte.", "erradas": ["A) Descreve obrigações/passivo, não ativo circulante.", "B) Fala em direitos realizáveis após o exercício seguinte, o que aponta para longo prazo.", "D) Trata de valores integralizados pelos proprietários, relacionados ao patrimônio líquido."], "fundamento": "Lei 6.404/1976, art. 179, I, conforme a classificação do ativo circulante.", "pegadinha": "A banca troca “até/no curso do exercício seguinte” por “após o exercício seguinte”. Essa palavra muda a classificação."}'::jsonb WHERE id='563524';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — identificação das características e informações apresentadas.", "regra": "Passivo representa obrigações; o ativo é apresentado em ordem decrescente de liquidez; o patrimônio líquido representa recursos dos proprietários, e o balanço evidencia as contas patrimoniais em determinada data.", "passos": ["1) I é verdadeira: dívidas e compromissos a pagar compõem o passivo.", "2) II é verdadeira: o ativo é disposto em ordem decrescente de grau de liquidez.", "3) III é falsa: recursos dos proprietários pertencem ao patrimônio líquido, não ao Passivo Exigível a Longo Prazo.", "4) IV é verdadeira: o balanço evidencia as contas patrimoniais em determinada data.", "5) Logo, I, II e IV são verdadeiras."], "calculo": "Não há cálculo.", "correta": "A — as assertivas I, II e IV.", "erradas": ["B) Inclui III, que está errada.", "C) Inclui III, que está errada.", "D) Exclui I e inclui III; portanto não corresponde ao conjunto verdadeiro."], "fundamento": "Lei 6.404/1976, arts. 178 e 179, sobre grupos patrimoniais e apresentação do balanço.", "pegadinha": "Confundir patrimônio líquido com passivo exigível. O PL não é uma dívida da empresa perante terceiros."}'::jsonb WHERE id='563529';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo dos saldos por grupos patrimoniais.", "regra": "A questão depende dos saldos apresentados na tabela original para classificar e totalizar ativo circulante, ativo não circulante, passivo circulante e passivo não circulante.", "passos": ["1) O trecho disponível no banco contém a pergunta e as alternativas, mas não contém a tabela com os saldos necessários.", "2) Sem esses dados, não é possível reconstruir de forma segura os quatro valores.", "3) O gabarito registrado no banco é B, mas a conta não deve ser inventada a partir das alternativas."], "calculo": "Não calculável com segurança a partir do texto extraído disponível.", "correta": "B — gabarito registrado na base. A conferência matemática depende da tabela original.", "erradas": ["A/C/D) Não é possível eliminar ou confirmar com segurança sem os dados da tabela original."], "fundamento": "Balanço Patrimonial — classificação entre ativo circulante, ativo não circulante, passivo circulante e passivo não circulante.", "pegadinha": "Questões com tabela/imagem exigem os dados originais. Não substitua informação ausente por uma inferência baseada apenas nas alternativas.", "verificacao": "Conferir a tabela da questão no PDF/TEC antes de considerar a resolução matemática fechada."}'::jsonb WHERE id='1058448';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — classificação do ativo não circulante.", "regra": "O ativo não circulante é subdividido em realizável a longo prazo, investimentos, imobilizado e intangível.", "passos": ["1) As alternativas A–D apresentam critérios típicos de classificação como circulante ou equivalentes de caixa.", "2) O enunciado pede o critério de classificação do ativo não circulante.", "3) A alternativa E apresenta sua subdivisão em realizável a longo prazo, investimentos, imobilizado e intangível."], "calculo": "Não há cálculo.", "correta": "E — ser subdividido em realizável a longo prazo, investimentos, imobilizado e intangível.", "erradas": ["A) É critério de ativo circulante.", "B) É critério de ativo mantido para negociação.", "C) Realização até 12 meses aponta para circulante.", "D) Trata de caixa/equivalentes de caixa e restrição de uso."], "fundamento": "Lei 6.404/1976, art. 179, II e seguintes, sobre o ativo não circulante.", "pegadinha": "A banca coloca vários critérios de ativo circulante para fazer você ignorar a pergunta sobre a estrutura do não circulante."}'::jsonb WHERE id='953144';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — apuração do patrimônio líquido a partir do balancete.", "regra": "Patrimônio Líquido = Capital Social + Reserva de Lucros, considerando que a depreciação acumulada reduz o ativo e não é conta do PL.", "passos": ["1) Capital Social = R$ 550.000,00.", "2) Reserva de Lucros = R$ 80.740,00.", "3) PL = 550.000 + 80.740 = R$ 630.740,00.", "4) A depreciação acumulada não é subtraída novamente do PL; ela é conta redutora do ativo."], "calculo": "PL = 550.000 + 80.740 = R$ 630.740,00.", "correta": "C — R$ 630.740,00.", "erradas": ["A) Considera apenas o capital e ignora a reserva.", "B) Não corresponde à soma das contas de patrimônio líquido apresentadas.", "D) Confunde total de débitos/ativos com patrimônio líquido."], "fundamento": "Lei 6.404/1976 — estrutura do patrimônio líquido; princípios de classificação patrimonial.", "pegadinha": "Depreciação acumulada é redutora do ativo, não uma conta que se soma ou subtrai diretamente do PL para responder à pergunta."}'::jsonb WHERE id='926995';
UPDATE questoes SET resolution='{"cobranca": "Patrimônio Líquido — cálculo da variação total no exercício.", "regra": "Aumento de capital e lucro aumentam o PL; dividendos distribuídos reduzem o PL. A constituição de reserva de lucros é uma transferência interna dentro do PL e não altera sua variação total.", "passos": ["1) Aumento de capital: +R$ 300.000.", "2) Lucro líquido: +R$ 180.000.", "3) Dividendos distribuídos: −R$ 126.000.", "4) Reserva de lucros de R$ 54.000 é destinação do lucro e não gera nova variação total do PL.", "5) Variação = 300.000 + 180.000 − 126.000 = R$ 354.000."], "calculo": "R$ 300.000 + R$ 180.000 − R$ 126.000 = R$ 354.000.", "correta": "A — R$ 354.000,00.", "erradas": ["B) Acrescenta indevidamente a reserva como nova variação.", "C) Não corresponde ao efeito líquido das mutações.", "D) Confunde saldo final do PL com sua variação."], "fundamento": "Lei 6.404/1976 — mutações do patrimônio líquido e destinação do resultado.", "pegadinha": "Reserva constituída com parte do lucro não é um novo aumento do PL; é apenas uma mudança de composição interna."}'::jsonb WHERE id='927001';
UPDATE questoes SET resolution='{"cobranca": "Patrimônio Líquido — capital social autorizado, subscrito e a realizar.", "regra": "Capital autorizado é o limite previsto para aumento de capital. A diferença entre o capital autorizado e o capital a subscrever corresponde ao capital já subscrito.", "passos": ["1) Capital autorizado representa o montante máximo autorizado para subscrição.", "2) Capital a subscrever é a parcela ainda não subscrita.", "3) Portanto, autorizado − a subscrever = capital subscrito."], "calculo": "Capital autorizado − capital a subscrever = capital social subscrito.", "correta": "B — Capital social subscrito.", "erradas": ["A/D) Realizado/integralizado dizem respeito à parcela efetivamente entregue pelos acionistas.", "C/E) A realizar/a integralizar representam parcela subscrita que ainda não foi integralizada."], "fundamento": "Lei nº 6.404/1976 e conceitos de capital social autorizado, subscrito e integralizado.", "pegadinha": "Subscrição não significa integralização: primeiro o acionista subscreve, depois integraliza o capital subscrito.", "verificacao": "Conceito compatível com a terminologia societária."}'::jsonb WHERE id='926987';
UPDATE questoes SET resolution='{"cobranca": "Patrimônio Líquido — identificação da afirmativa incorreta.", "regra": "Reserva de lucros é formada por parcelas do lucro destinadas segundo a legislação e deliberações aplicáveis; não é o valor integralizado pelos acionistas. Ações em tesouraria são conta redutora do PL; capital realizado é capital integralizado; reserva legal, em regra, recebe 5% do lucro líquido até os limites legais; ajustes de avaliação patrimonial registram determinados efeitos de avaliação a valor justo.", "passos": ["1) Analise cada alternativa.", "2) A alternativa C define reserva de lucros como valor integralizado pelos acionistas.", "3) Essa descrição corresponde ao capital, não à reserva de lucros.", "4) Logo, C é a incorreta."], "calculo": "Não há cálculo.", "correta": "C — Reserva de lucros não é o valor integralizado pelos acionistas.", "erradas": ["A) Correta: ações em tesouraria aparecem como conta redutora do PL.", "B) Correta no sentido de capital realizado/integralizado.", "D) Correta quanto à destinação ordinária de 5% para reserva legal, observados os limites da Lei 6.404/1976.", "E) A alternativa descreve a função do ajuste de avaliação patrimonial de forma compatível com a questão."], "fundamento": "Lei nº 6.404/1976, especialmente as regras de Patrimônio Líquido e reserva legal.", "pegadinha": "Não confundir capital integralizado com reserva de lucros: um vem da participação dos acionistas; o outro decorre da destinação de lucros.", "verificacao": "A resposta registrada é C."}'::jsonb WHERE id='926989';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — cálculo do Ativo.", "regra": "O Ativo reúne bens e direitos. Contas de passivo e patrimônio líquido não entram na soma do Ativo.", "passos": ["1) Separe os bens e direitos: Móveis e Utensílios, Banco, Estoque e Veículos.", "2) Some R$ 15.000 + R$ 358.750 + R$ 2.500 + R$ 40.000.", "3) O total encontrado é R$ 416.250.", "4) Compare com as alternativas."], "calculo": "15.000 + 358.750 + 2.500 + 40.000 = R$ 416.250,00.", "correta": "C — R$ 416.250,00.", "erradas": ["A/B/D/E) Decorrem de somas incompletas ou da inclusão indevida de contas que não pertencem ao Ativo."], "fundamento": "Estrutura do Balanço Patrimonial: Ativo compreende recursos controlados pela entidade, resultantes de eventos passados, dos quais se esperam benefícios econômicos futuros.", "pegadinha": "Capital social, notas promissórias a pagar, duplicatas a pagar e financiamentos a pagar são PL/Passivo, não Ativo.", "verificacao": "O cálculo fecha exatamente com a alternativa C."}'::jsonb WHERE id='927636';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — ordem de apresentação das contas do Ativo.", "regra": "No Ativo, as contas são dispostas em ordem decrescente de liquidez dos elementos nelas registrados, nos grupos previstos na legislação societária.", "passos": ["1) Identifique a característica pedida: ordem de apresentação no Ativo.", "2) A Lei 6.404/1976 adota a ordem decrescente de liquidez.", "3) Portanto, a combinação correta é “decrescente / liquidez”."], "calculo": "Não há cálculo.", "correta": "B — decrescente / liquidez.", "erradas": ["A/C/E) Trazem ordem crescente ou critério diferente de liquidez.", "D) “Obrigação” não é o critério de ordenação do Ativo."], "fundamento": "Lei nº 6.404/1976, art. 178, estrutura do Balanço Patrimonial.", "pegadinha": "Liquidez é a facilidade de conversão em dinheiro; não confundir com exigibilidade, que é característica do Passivo.", "verificacao": "Resposta registrada: B."}'::jsonb WHERE id='927646';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial — identificação e soma das contas do Ativo.", "regra": "Receitas e despesas pertencem ao resultado; salários e contas a pagar são passivos. Para calcular o Ativo, somam-se os bens e direitos listados.", "passos": ["1) Separe as contas do Ativo: Caixa, Banco, Clientes e Veículos.", "2) Some R$ 6.500 + R$ 2.500 + R$ 5.650 + R$ 16.000.", "3) O resultado é R$ 30.650."], "calculo": "6.500 + 2.500 + 5.650 + 16.000 = R$ 30.650,00.", "correta": "C — R$ 30.650,00.", "erradas": ["A) Considera apenas parte do Ativo.", "B/D/E) Incluem ou excluem contas indevidamente ao montar a soma do Ativo."], "fundamento": "Balanço Patrimonial e classificação das contas em Ativo, Passivo e Patrimônio Líquido.", "pegadinha": "Não some receita, despesa, custo ou obrigações na composição do Ativo.", "verificacao": "O cálculo fecha com a alternativa C."}'::jsonb WHERE id='927676';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas da informação financeira útil no CPC 00/NBC TG Estrutura Conceitual.", "regra": "Relevância e representação fidedigna são características fundamentais. Comparabilidade, capacidade de verificação, tempestividade e compreensibilidade são características qualitativas de melhoria.", "passos": ["1) Classifique cada item.", "2) I = tempestividade: melhoria.", "3) II = relevância: fundamental.", "4) III = comparabilidade: melhoria.", "5) IV = capacidade de verificação: melhoria.", "6) V = representação fidedigna: fundamental.", "7) VI = compreensibilidade: melhoria.", "8) Portanto, I, III, IV e VI formam o grupo de melhoria."], "calculo": "", "correta": "B) I, III, IV e VI são características qualitativas de melhoria.", "erradas": ["A) Classifica II e V como fundamentais — essa parte isoladamente está correta, mas não corresponde ao conjunto pedido.", "C) Coloca I como fundamental — incorreto.", "D) Coloca II e V como melhoria — incorreto.", "E) Coloca III como fundamental — incorreto."], "fundamento": "NBC TG Estrutura Conceitual / CPC 00: características qualitativas fundamentais (relevância e representação fidedigna) e de melhoria (comparabilidade, verificabilidade, tempestividade e compreensibilidade).", "pegadinha": "A principal armadilha é decorar “fundamentais” e “melhoria” sem separar os dois grupos."}'::jsonb WHERE id='3120008';
UPDATE questoes SET resolution='{"cobranca": "Elementos das demonstrações: posição financeira x desempenho financeiro.", "regra": "Ativo, passivo e patrimônio líquido são elementos relacionados à posição financeira. Receita e despesa são relacionadas ao desempenho financeiro.", "passos": ["1) Elimine despesa e receita, pois são elementos de desempenho.", "2) Ativo e passivo também pertencem à posição financeira.", "3) Patrimônio líquido integra a representação da posição financeira.", "4) Logo, E é a definição compatível."], "calculo": "", "correta": "E) patrimônio líquido se refere à posição financeira da entidade que reporta.", "erradas": ["A) Despesa se relaciona ao desempenho financeiro.", "B) Ativo se relaciona à posição financeira, não ao desempenho.", "C) Passivo se relaciona à posição financeira.", "D) Receita se relaciona ao desempenho financeiro."], "fundamento": "NBC TG Estrutura Conceitual / CPC 00, conceitos dos elementos das demonstrações contábeis.", "pegadinha": "A FAFIPA explora a troca entre “posição financeira” e “desempenho financeiro”."}'::jsonb WHERE id='3120011';
UPDATE questoes SET resolution='{"cobranca": "Base de mensuração: valor em uso.", "regra": "Valor em uso é o valor presente dos fluxos de caixa, ou outros benefícios econômicos, que a entidade espera obter do uso do ativo e de sua alienação final.", "passos": ["1) Identifique que a pergunta pede a definição de valor em uso.", "2) Compare as alternativas com as bases de mensuração conhecidas.", "3) A definição correta é a que considera os benefícios econômicos futuros do uso do ativo e sua alienação final, trazidos a valor presente."], "calculo": "", "correta": "A) o valor presente dos fluxos de caixa, ou outros benefícios econômicos, que a entidade espera obter do uso de ativo e de sua alienação final.", "erradas": ["B) Refere-se ao valor presente dos recursos que a entidade espera transferir para cumprir obrigação, conceito ligado a valor de cumprimento.", "C) É custo histórico.", "D) É custo de reposição/reprodução de ativo equivalente.", "E) É preço de saída em transação ordenada, associado ao valor justo."], "fundamento": "NBC TG Estrutura Conceitual / CPC 00, bases de mensuração.", "pegadinha": "Diferenciar valor em uso, custo histórico, custo de reposição e valor justo."}'::jsonb WHERE id='3120013';
UPDATE questoes SET resolution='{"cobranca": "Bases de mensuração – CPC 00", "regra": "Custo corrente usa informações atuais de preço/custo; valor justo é preço de saída em transação ordenada; valor em uso é valor presente dos benefícios esperados do uso e alienação; valor de cumprimento é o valor presente dos recursos a transferir para cumprir obrigação; custo histórico parte dos custos da aquisição/criação.", "passos": ["1) Primeira afirmação: Falsa. A descrição apresentada não corresponde ao custo corrente; ela descreve características de mensuração baseadas no evento original.", "2) Segunda: Verdadeira. É a definição de valor justo.", "3) Terceira: Verdadeira. É a definição de valor em uso.", "4) Quarta: Verdadeira. É a definição de valor de cumprimento.", "5) Quinta: Falsa. A descrição é de custo corrente, não de custo histórico.", "6) Sequência F-V-V-V-F → alternativa A."], "calculo": "Não há cálculo.", "correta": "A) F; V; V; V; F.", "erradas": ["B) Torna falsas as afirmações III e IV, que estão de acordo com as definições.", "C) Inverte a classificação das duas primeiras afirmações.", "D) Considera verdadeira a descrição do custo corrente como custo histórico."], "fundamento": "NBC TG Estrutura Conceitual – bases de mensuração.", "pegadinha": "Diferencie custo histórico de custo corrente: histórico olha para os custos da aquisição/criação; corrente considera o custo de um ativo equivalente na data da mensuração."}'::jsonb WHERE id='2746467';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas da informação financeira", "regra": "As características fundamentais são relevância e representação fidedigna. As características de melhoria são comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "passos": ["1) I descreve compreensibilidade: verdadeiro.", "2) II descreve representação fidedigna: verdadeiro.", "3) III descreve comparabilidade: verdadeiro.", "4) IV descreve relevância: verdadeiro.", "5) V descreve capacidade de verificação: verdadeiro.", "6) VI descreve tempestividade: verdadeiro.", "7) Portanto, a alternativa que identifica corretamente as características de melhoria é A."], "calculo": "Não há cálculo.", "correta": "A) Comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "erradas": ["B) Relevância e representação fidedigna são características fundamentais, não de melhoria.", "C) Lista as características de melhoria como se fossem fundamentais.", "D) Novamente classifica características de melhoria como fundamentais."], "fundamento": "NBC TG Estrutura Conceitual – características qualitativas fundamentais e de melhoria.", "pegadinha": "Memorize a divisão: FUNDAMENTAIS = relevância + representação fidedigna; MELHORIA = comparabilidade + verificabilidade + tempestividade + compreensibilidade."}'::jsonb WHERE id='2746469';
UPDATE questoes SET resolution='{"cobranca": "Reconhecimento de despesas – CPC 00", "regra": "A despesa é reconhecida quando ocorre diminuição de ativos ou aumento de passivos que resulta em diminuição do patrimônio líquido, exceto distribuições aos proprietários. O reconhecimento ocorre, em particular, com reconhecimento/aumento de passivo ou desreconhecimento/diminuição de ativo.", "passos": ["1) I: não é regra geral. Reconhecimento inicial ou aumento de ativo normalmente se relaciona a reconhecimento de ativo, não de despesa.", "2) II: verdadeiro; o reconhecimento inicial/aumento de passivo pode resultar no reconhecimento de despesa.", "3) III: verdadeiro; desreconhecimento/diminuição de ativo pode resultar em despesa.", "4) IV: não é a regra geral indicada; diminuição de passivo pode representar aumento de patrimônio líquido/receita, e não despesa.", "5) Logo, II e III apenas → alternativa A."], "calculo": "Não há cálculo.", "correta": "A) II e III, apenas.", "erradas": ["B) Inclui I e IV, que não correspondem à regra geral de reconhecimento de despesa.", "C) Considera I e IV corretas.", "D) Considera I correta e exclui III.", "E) Inclui IV e exclui III."], "fundamento": "NBC TG Estrutura Conceitual – reconhecimento de receitas e despesas e definição de despesa.", "pegadinha": "Não confunda toda variação patrimonial com despesa: aumento de ativo pode representar receita/contrapartida, e redução de passivo pode representar receita."}'::jsonb WHERE id='3998517';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas de melhoria", "regra": "As quatro características qualitativas de melhoria são comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "passos": ["1) Relevância e representação fidedigna são características fundamentais.", "2) Comparabilidade, capacidade de verificação, tempestividade e compreensibilidade são características de melhoria.", "3) A alternativa B reproduz exatamente as quatro características de melhoria."], "calculo": "Não há cálculo.", "correta": "B) Comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "erradas": ["A) Inclui relevância, que é fundamental.", "C) Inclui relevância e representação fidedigna, que são fundamentais.", "D) Inclui representação fidedigna, que é fundamental.", "E) Inclui relevância e representação fidedigna."], "fundamento": "NBC TG Estrutura Conceitual – características qualitativas.", "pegadinha": "Se aparecer “relevância” ou “representação fidedigna” numa lista apresentada como características de melhoria, desconfie: elas são fundamentais."}'::jsonb WHERE id='2153421';
UPDATE questoes SET resolution='{"cobranca": "Definição de passivo – CPC 00", "regra": "Passivo é uma obrigação presente da entidade de transferir um recurso econômico como resultado de eventos passados.", "passos": ["1) A obrigação precisa ser presente na data de reporte.", "2) O objeto da transferência é um recurso econômico, não apenas “recurso financeiro”.", "3) A origem é constituída por eventos passados.", "4) A combinação presente – econômico – passados corresponde à alternativa E."], "calculo": "Não há cálculo.", "correta": "E) presente – econômico – passados.", "erradas": ["A) Erra o momento da obrigação e dos eventos.", "B) Erra a temporalidade e limita o recurso a financeiro.", "C) Trata a obrigação como passada, quando ela é presente.", "D) Trata a obrigação como futura."], "fundamento": "NBC TG Estrutura Conceitual – definição de passivo.", "pegadinha": "A definição atual usa “recurso econômico”; não confunda recurso econômico com apenas dinheiro ou recurso financeiro."}'::jsonb WHERE id='2153424';
UPDATE questoes SET resolution='{"cobranca": "Bases de mensuração – CPC 00", "regra": "Valor justo é preço de venda/transferência em transação ordenada; custo histórico usa os custos da aquisição/criação; valor em uso é o valor presente dos benefícios do uso e alienação; custo corrente é o custo de ativo equivalente na data da mensuração; valor de cumprimento é o valor presente dos recursos que a entidade espera transferir para cumprir a obrigação.", "passos": ["1) I = valor justo.", "2) II = custo histórico.", "3) III = valor em uso.", "4) IV = custo corrente.", "5) V = valor de cumprimento.", "6) A sequência valor justo; custo histórico; valor em uso; custo corrente; valor de cumprimento corresponde à alternativa A."], "calculo": "Não há cálculo.", "correta": "A) I – valor justo; II – custo histórico; III – valor em uso; IV – custo corrente; V – valor de cumprimento.", "erradas": ["B) Troca custo corrente e custo histórico nas posições II/IV.", "C) Inverte as duas primeiras bases e termina com valor justo no lugar de valor de cumprimento.", "D) Troca valor justo/valor em uso e valor de cumprimento/valor justo.", "E) Também troca as definições de valor justo/valor em uso e histórico/corrente."], "fundamento": "NBC TG Estrutura Conceitual – bases de mensuração.", "pegadinha": "Associe as expressões-chave: “preço recebido na venda” = valor justo; “custos incorridos na aquisição” = histórico; “uso e alienação final” = valor em uso; “ativo equivalente hoje” = corrente."}'::jsonb WHERE id='2153434';
UPDATE questoes SET resolution='{"cobranca": "Bases de mensuração – CPC 00", "regra": "Valor justo = preço de saída em mercado; valor em uso = valor presente dos benefícios esperados do uso e alienação; custo histórico = custos incorridos na aquisição/criação; custo corrente = custo de ativo equivalente na data da mensuração.", "passos": ["1) I: “preço recebido pela venda” → valor justo.", "2) II: “fluxos de caixa/benefícios do uso e alienação final” → valor em uso.", "3) III: “custos incorridos na aquisição/criação” → custo histórico.", "4) IV: “custo de ativo equivalente na data de mensuração” → custo corrente.", "5) Sequência valor justo, valor em uso, custo histórico, custo corrente → alternativa D."], "calculo": "Não há cálculo.", "correta": "D) I – valor justo; II – valor em uso; III – custo histórico; IV – custo corrente.", "erradas": ["A) Troca valor justo e valor em uso.", "B) Coloca custo corrente no lugar de valor em uso.", "C) Troca valor justo por valor em uso e histórico/corrente."], "fundamento": "NBC TG Estrutura Conceitual – bases de mensuração.", "pegadinha": "“Preço que seria recebido pela venda” é valor justo; “benefícios econômicos do uso” é valor em uso."}'::jsonb WHERE id='2431261';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas fundamentais", "regra": "As características qualitativas fundamentais da informação financeira útil são relevância e representação fidedigna.", "passos": ["1) Relevância significa capacidade de fazer diferença nas decisões dos usuários.", "2) Representação fidedigna exige que o fenômeno seja representado de forma completa, neutra e livre de erro, dentro dos limites da informação.", "3) As demais opções combinam características de melhoria.", "4) Portanto, a alternativa B é correta."], "calculo": "Não há cálculo.", "correta": "B) Relevância e representação fidedigna.", "erradas": ["A) Tempestividade e comparabilidade são de melhoria.", "C) Compreensibilidade é de melhoria.", "D) Capacidade de verificação é de melhoria.", "E) Comparabilidade e capacidade de verificação são de melhoria."], "fundamento": "NBC TG Estrutura Conceitual – características qualitativas fundamentais.", "pegadinha": "A dupla que deve ser memorizada é: RELEVÂNCIA + REPRESENTAÇÃO FIDEDIGNA."}'::jsonb WHERE id='1741028';
UPDATE questoes SET resolution='{"cobranca": "Definição de ativo – CPC 00", "regra": "Ativo é um recurso econômico presente controlado pela entidade como resultado de eventos passados.", "passos": ["1) A palavra-chave é “presente”: o recurso econômico existe na data de reporte.", "2) A entidade precisa controlá-lo.", "3) O controle decorre de eventos passados.", "4) Portanto, presente – passados → alternativa C."], "calculo": "Não há cálculo.", "correta": "C) presente – passados.", "erradas": ["A) Usa eventos futuros, contrariando a definição.", "B) Inverte a temporalidade do recurso e dos eventos.", "D) Classifica o recurso como passado.", "E) Também coloca o recurso como passado."], "fundamento": "NBC TG Estrutura Conceitual – definição de ativo.", "pegadinha": "Na definição atual, “ativo” é recurso econômico PRESENTE; o evento que originou o controle é PASSADO."}'::jsonb WHERE id='1741032';
UPDATE questoes SET resolution='{"cobranca": "Valor justo – CPC 00", "regra": "Valor justo é uma mensuração baseada em premissas de participantes do mercado e corresponde ao preço que seria recebido pela venda de ativo ou pago pela transferência de passivo em transação ordenada na data de mensuração.", "passos": ["1) A questão fala em premissas de participantes do mercado.", "2) Também menciona o preço que seria recebido numa venda.", "3) Esses elementos identificam o valor justo.", "4) Portanto, alternativa D."], "calculo": "Não há cálculo.", "correta": "D) Valor justo.", "erradas": ["A) “Custo presente” não é a base descrita.", "B) Valor em uso considera benefícios do uso pela entidade, não preço de mercado.", "C) Custo histórico parte dos custos de aquisição/criação."], "fundamento": "NBC TG Estrutura Conceitual – valor justo.", "pegadinha": "“Participantes do mercado” e “preço recebido pela venda” apontam diretamente para valor justo."}'::jsonb WHERE id='1972567';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas de melhoria", "regra": "Comparabilidade, capacidade de verificação, tempestividade e compreensibilidade são características qualitativas de melhoria.", "passos": ["1) Relevância e representação fidedigna são fundamentais.", "2) A alternativa A traz duas características de melhoria: tempestividade e comparabilidade.", "3) As demais alternativas misturam características fundamentais com de melhoria.", "4) Portanto, A."], "calculo": "Não há cálculo.", "correta": "A) Tempestividade e comparabilidade.", "erradas": ["B) Relevância e representação fidedigna são fundamentais.", "C) Relevância é fundamental.", "D) Capacidade de verificação é de melhoria, mas relevância é fundamental.", "E) Compreensibilidade é de melhoria, mas representação fidedigna é fundamental."], "fundamento": "NBC TG Estrutura Conceitual – características qualitativas.", "pegadinha": "Quando a alternativa mistura “relevância” ou “representação fidedigna” com as de melhoria, ela está classificando grupos diferentes."}'::jsonb WHERE id='2165646';
UPDATE questoes SET resolution='{"cobranca": "Identificação das bases de mensuração", "regra": "No quadro da questão, cada descrição deve ser associada à base de mensuração correspondente: valor em uso, custo histórico, custo corrente e valor justo.", "passos": ["1) “Valor presente de fluxos de caixa futuros do uso do ativo e alienação final” → valor em uso (IV).", "2) “Informações derivadas do preço da transação/evento que deu origem ao ativo; custos de transação...” → custo histórico (I).", "3) “Reflete os preços vigentes no momento do consumo ou cumprimento; custo de ativo equivalente” → custo corrente (II).", "4) “Preço que seria recebido para vender o ativo” → valor justo (III).", "5) Sequência IV, I, II, III → alternativa E."], "calculo": "Não há cálculo; é associação conceitual.", "correta": "E) IV, I, II e III.", "erradas": ["A) Coloca custo corrente na primeira posição e troca a ordem do quadro.", "B) Começa por custo corrente e desloca as demais bases.", "C) Inverte custo corrente e valor justo.", "D) Coloca valor justo no último item, contrariando a descrição de preço de venda."], "fundamento": "NBC TG Estrutura Conceitual – bases de mensuração.", "pegadinha": "“Uso e alienação final” = valor em uso; “preço de venda” = valor justo. Essas duas pistas resolvem grande parte da questão."}'::jsonb WHERE id='2165647';
UPDATE questoes SET resolution='{"cobranca": "Reconhecimento de ativo – CPC 00", "regra": "O ativo é um recurso econômico presente controlado pela entidade; recurso econômico é um direito que tem potencial de produzir benefícios econômicos. A questão, na formulação apresentada, cobra a ideia de benefícios econômicos futuros associada ao reconhecimento de ativo.", "passos": ["1) A alternativa B é o gabarito registrado no caderno.", "2) Forma física não é requisito: um direito pode ser ativo.", "3) Direito de propriedade não é requisito absoluto: controle pode existir sem propriedade formal.", "4) Controle legal também não é requisito absoluto.", "5) A alternativa E não expressa a condição econômica essencial cobrada pela questão."], "calculo": "Não há cálculo.", "correta": "B) Benefícios econômicos futuros.", "erradas": ["A) Ativo não precisa ter forma física.", "C) Propriedade jurídica não é requisito indispensável em todos os casos.", "D) Controle legal não é requisito indispensável.", "E) Eventos previstos não são, por si, suficientes para reconhecer um ativo presente."], "fundamento": "NBC TG Estrutura Conceitual – definição de ativo e potencial de produzir benefícios econômicos.", "pegadinha": "Cuidado com a redação histórica versus a definição atual do CPC 00: a definição atual enfatiza “recurso econômico presente” e potencial de produzir benefícios econômicos."}'::jsonb WHERE id='1335864';
UPDATE questoes SET resolution='{"cobranca": "Balanço Patrimonial e elementos patrimoniais", "regra": "Ativo representa aplicações de recursos; passivo e patrimônio líquido representam origens. A natureza normal das contas do passivo é credora, e o capital pode ser integralizado por bens/direitos, não necessariamente dinheiro.", "passos": ["1) I: incorreta na formulação atual, pois a definição de ativo não exige uma “perspectiva intrínseca de benefícios futuros”; o conceito atual é recurso econômico presente controlado.", "2) II: correta — ativo como aplicação e passivo/PL como origem é a visão clássica.", "3) III: incorreta — contas do passivo podem sofrer débitos e créditos, mas sua natureza normal é credora, não devedora.", "4) IV: incorreta — integralização de capital não precisa ocorrer sempre em dinheiro; pode envolver bens ou direitos conforme a legislação societária.", "5) V: correta — o PL é composto pelas contas previstas na legislação societária, observadas as alterações legais.", "6) Há três assertivas incorretas (I, III e IV). Isso gera uma inconsistência com as alternativas, pois D afirma apenas duas incorretas. Portanto, o gabarito registrado D deve ser conferido no original."], "calculo": "Não há cálculo.", "correta": "Gabarito registrado: D. Porém, a análise das cinco assertivas pelo texto extraído aponta I, III e IV como incorretas; questão deve ser conferida no original.", "erradas": ["A) Não, porque há assertivas incorretas.", "B) Não, há mais de uma assertiva incorreta.", "C) Não, a contagem pelo texto extraído não resulta em duas corretas.", "D) É o gabarito registrado, mas a contagem aparente pelo texto extraído gera inconsistência.", "E) Não, II e V são defensáveis como corretas."], "fundamento": "NBC TG Estrutura Conceitual; Lei nº 6.404/1976, art. 178 e estrutura do patrimônio líquido.", "pegadinha": "Questões antigas podem usar linguagem anterior do CPC 00. Aqui, não vale forçar o gabarito: a redação extraída e a alternativa D precisam ser conferidas na fonte original."}'::jsonb WHERE id='916309';
UPDATE questoes SET resolution='{"cobranca": "Características qualitativas de melhoria", "regra": "As características qualitativas de melhoria são comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "passos": ["1) Comparabilidade é de melhoria.", "2) Verificabilidade/capacidade de verificação é de melhoria.", "3) Tempestividade é de melhoria.", "4) Compreensibilidade é de melhoria.", "5) A alternativa C reúne exatamente as quatro."], "calculo": "Não há cálculo.", "correta": "C) Comparabilidade, Verificabilidade, Tempestividade e Compreensibilidade.", "erradas": ["A) Coercibilidade não é característica qualitativa da informação financeira.", "B) Relevância é fundamental, e “registro pelo valor original” não é característica de melhoria.", "D) Registro pelo valor original não integra as quatro características de melhoria."], "fundamento": "NBC TG Estrutura Conceitual – características qualitativas de melhoria.", "pegadinha": "Não confunda características qualitativas com princípios/atributos de mensuração ou reconhecimento. “Registro pelo valor original” não pertence a esse grupo."}'::jsonb WHERE id='1058686';
UPDATE questoes SET resolution='{"regra": "No CPC 00, passivo é uma obrigação presente da entidade, derivada de eventos passados, cuja liquidação se espera que resulte na saída de recursos capazes de gerar benefícios econômicos.", "passos": ["O comando pede a definição de passivo.", "Procure os três elementos centrais: obrigação presente, evento passado e saída de recursos na liquidação.", "A alternativa E reúne exatamente esses elementos.", "As demais alteram um desses elementos ou descrevem patrimônio líquido."], "calculo": "Não há cálculo.", "correta": "E — obrigação presente, derivada de eventos passados, cuja liquidação se espera que resulte na saída de recursos capazes de gerar benefícios econômicos.", "erradas": ["A) Fala em entrada de recursos, característica incompatível com a liquidação de um passivo.", "B) Também fala em entrada de recursos.", "C) Define interesse residual dos ativos, relacionado ao patrimônio líquido.", "D) Vincula a obrigação a eventos futuros, e não passados."], "fundamento": "CPC 00 — Estrutura Conceitual, definição de passivo e seus elementos.", "pegadinha": "A FAFIPA pode trocar “saída” por “entrada” ou “eventos passados” por “eventos futuros”. Esses dois pontos são decisivos.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 201}'::jsonb WHERE id='1336858';
UPDATE questoes SET resolution='{"regra": "Despesas representam decréscimos nos benefícios econômicos futuros relacionados ao decréscimo de ativo ou aumento de passivo, que podem ser mensurados com confiabilidade na formulação tradicional usada pelo enunciado.", "passos": ["Identifique que a questão pede o reconhecimento de despesas.", "Despesa está associada a uma diminuição de benefícios econômicos futuros.", "Essa diminuição pode ocorrer pela redução de um ativo ou pelo aumento de um passivo.", "A alternativa C reproduz essa estrutura."], "calculo": "Não há cálculo.", "correta": "C — decréscimo nos benefícios econômicos futuros relacionado ao decréscimo de um ativo ou aumento de um passivo, com mensuração confiável.", "erradas": ["A) Fala em aumento de benefícios econômicos, o que não caracteriza despesa.", "B) Troca os sinais patrimoniais e fala em decréscimo de benefícios presentes.", "D) Fala em acréscimo de ativo e dispensa mensuração.", "E) Inverte a relação entre passivo e ativo."], "fundamento": "CPC 00/R1, conforme a formulação apresentada no material da questão sobre reconhecimento de despesas.", "pegadinha": "Memorize a lógica: despesa reduz benefícios econômicos futuros; isso normalmente aparece como redução de ativo ou aumento de passivo.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 202}'::jsonb WHERE id='1336859';
UPDATE questoes SET resolution='{"regra": "Na Estrutura Conceitual, relevância e representação fidedigna são características qualitativas fundamentais; comparabilidade, verificabilidade, tempestividade e compreensibilidade são características qualitativas de melhoria.", "passos": ["Relevância é fundamental → V.", "Comparabilidade é de melhoria → F.", "Representação fidedigna é fundamental → F na afirmação que a chama de melhoria.", "Verificabilidade é de melhoria → V.", "Tempestividade é de melhoria → V.", "A sequência é V-F-F-V-V."], "calculo": "Não há cálculo.", "correta": "B — V, F, F, V, V.", "erradas": ["A) Classifica todas como verdadeiras, inclusive comparabilidade e representação fidedigna.", "C) Inverte a classificação de representação fidedigna e verificabilidade.", "D) Classifica relevância como falsa."], "fundamento": "NBC TG Estrutura Conceitual/CPC 00: características qualitativas fundamentais e de melhoria.", "pegadinha": "Decore a divisão: fundamentais = relevância + representação fidedigna; melhoria = comparabilidade + verificabilidade + tempestividade + compreensibilidade.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 205}'::jsonb WHERE id='825557';
UPDATE questoes SET resolution='{"regra": "A redução dos benefícios econômicos futuros, associada à redução de ativo ou aumento de passivo e mensurável de forma confiável, corresponde ao reconhecimento de despesa na formulação indicada pelo CPC 00/R1.", "passos": ["Observe o primeiro sinal: decréscimo nos benefícios econômicos futuros.", "Observe a contrapartida: decréscimo de ativo ou aumento de passivo.", "Essa combinação caracteriza despesa.", "Logo, a resposta é reconhecimento de despesas."], "calculo": "Não há cálculo.", "correta": "D — Reconhecimento de despesas.", "erradas": ["A) Ativos não são reconhecidos por essa combinação de efeitos.", "B) Passivos possuem critérios próprios de reconhecimento.", "C) Receita representa aumento, não decréscimo, de benefícios econômicos."], "fundamento": "CPC 00/R1, conforme o critério de reconhecimento apresentado no enunciado.", "pegadinha": "O sinal econômico é decisivo: redução de benefícios futuros aponta para despesa, não receita.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 208}'::jsonb WHERE id='635039';
UPDATE questoes SET resolution='{"regra": "Valor presente corresponde à mensuração por fluxos de caixa futuros descontados. O ativo é mensurado pelo valor presente dos fluxos futuros de entrada líquida e o passivo pelo valor presente dos fluxos futuros de saída líquida.", "passos": ["Identifique a expressão “valor presente”.", "Ela envolve fluxos futuros de caixa descontados.", "A alternativa B fala em custo histórico; C fala em custo corrente; D descreve valor realizável/liquidação.", "Portanto, a alternativa correta é B segundo a formulação apresentada no material."], "calculo": "Não há cálculo.", "correta": "B — Valor presente.", "erradas": ["A) A descrição apresentada corresponde à definição de valor presente, mas o material registra B como resposta; a formulação do enunciado/alternativas deve ser conferida na fonte original antes de usar a questão como modelo de gabarito.", "C) Descreve custo corrente.", "D) Descreve valor realizável/valor de liquidação."], "fundamento": "CPC 00/R1 — bases de mensuração.", "pegadinha": "Esta questão contém uma inconsistência textual entre o conceito descrito no enunciado e a alternativa indicada como gabarito. Não force a resposta sem conferir a fonte original.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 209}'::jsonb WHERE id='635053';
UPDATE questoes SET resolution='{"regra": "Verificabilidade é uma característica qualitativa de melhoria que ajuda a assegurar aos usuários que a informação representa fidedignamente o fenômeno que pretende representar, permitindo consenso entre observadores independentes, ainda que não absoluto.", "passos": ["Leia as quatro descrições.", "A descreve compreensibilidade.", "B descreve comparabilidade.", "C descreve tempestividade.", "D descreve verificabilidade."], "calculo": "Não há cálculo.", "correta": "D — diferentes observadores conscientes e independentes podem chegar a consenso, ainda que não completo, sobre a representação do fenômeno.", "erradas": ["A) Define compreensibilidade.", "B) Define comparabilidade.", "C) Define tempestividade."], "fundamento": "CPC 00/NBC TG Estrutura Conceitual — características qualitativas de melhoria.", "pegadinha": "Associe “observadores independentes” a verificabilidade. “A tempo de influenciar decisões” é tempestividade.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 210}'::jsonb WHERE id='938387';
UPDATE questoes SET resolution='{"regra": "Valor presente utiliza o desconto dos fluxos de caixa futuros. Ativos e passivos são mensurados considerando o valor presente dos fluxos líquidos futuros relacionados ao item ou à obrigação.", "passos": ["Procure a alternativa que menciona fluxos futuros descontados.", "A apresenta exatamente essa característica para ativos e passivos.", "B descreve custo histórico.", "C descreve custo corrente e D descreve valor realizável/valor de liquidação."], "calculo": "Não há cálculo.", "correta": "A — é a definição de valor presente apresentada na questão.", "erradas": ["B) Custo histórico: valores registrados na data da aquisição ou recebimento.", "C) Custo corrente: quanto teria de ser pago para adquirir o ativo equivalente na data do balanço.", "D) Valor realizável/valor de liquidação: montantes que poderiam ser obtidos ou pagos em condições próprias dessa base."], "fundamento": "CPC 00/R1 — bases de mensuração.", "pegadinha": "A palavra “descontado” e a referência a “fluxos futuros” praticamente entregam valor presente.", "cobranca": "Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)", "status": "individual", "rank_resolucao": 211}'::jsonb WHERE id='938389';
UPDATE questoes SET resolution='{"title": "Resolução individual — Questão 222", "whatTests": "Representação fidedigna no CPC 00 (R1).", "rule": "Para ser representação fidedigna, o retrato deve ser completo, neutro e livre de erro. A representação fidedigna não significa perfeição absoluta, mas maximização desses atributos na medida possível.", "steps": ["Localize os três atributos citados no enunciado.", "Complete + neutra + livre de erro são os atributos da representação fidedigna.", "Elimine comparabilidade, verificabilidade, tempestividade e compreensibilidade, que são outras características qualitativas."], "calculation": "Não há cálculo.", "whyCorrect": "A alternativa A corresponde diretamente à característica qualitativa descrita.", "whyWrong": "B é comparabilidade; C é verificabilidade; D é tempestividade; E é compreensibilidade.", "basis": "CPC 00 (R1) – Estrutura Conceitual, características qualitativas da informação financeira útil.", "fafipaTrap": "A banca apresenta termos próximos para testar a associação exata dos atributos.", "status": "resolvida"}'::jsonb WHERE id='953142';
UPDATE questoes SET resolution='{"what": "Escrituração inicial de seguro contratado com vigência futura.", "rule": "Em 05/03, nenhum mês de cobertura foi consumido. O prêmio total de R$ 9.000 é um gasto antecipado a apropriar ao longo dos 18 meses: R$ 500 por mês. A obrigação total é reconhecida na contratação, mesmo que o pagamento seja parcelado a partir de abril.", "steps": ["Calcular apropriação mensal: R$ 9.000 ÷ 18 = R$ 500.", "Na data da contratação, reconhecer o direito/gasto antecipado de R$ 9.000.", "Reconhecer o passivo de R$ 9.000.", "Não reconhecer despesa de R$ 500 em 05/03 porque a cobertura ainda não foi consumida."], "calc": "R$ 9.000 ÷ 18 = R$ 500 por mês. Em 05/03: débito em Seguros a Apropriar R$ 9.000 e crédito em Prêmios de Seguros a Pagar R$ 9.000.", "correct": "A — D Seguros a Apropriar R$ 9.000; C Prêmios de Seguros a Pagar R$ 9.000.", "wrong": "B reconhece despesa antes da competência; C reconhece despesa integral e ainda mistura apropriação parcial; D reconhece R$ 500 de despesa antes do consumo; E leva todo o prêmio à despesa imediatamente.", "basis": "Regime de competência e apropriação das despesas antecipadas conforme período de cobertura.", "trap": "O parcelamento não define a despesa: competência é determinada pelo período de cobertura do seguro."}'::jsonb WHERE id='3936161';
UPDATE questoes SET resolution='{"what": "Conceito de liquidez seca.", "rule": "A liquidez seca mede a capacidade de pagamento das obrigações de curto prazo considerando os ativos circulantes de maior liquidez, excluindo normalmente os estoques e outros itens menos líquidos.", "steps": ["Comparar com liquidez imediata: só disponibilidades.", "Comparar com liquidez corrente: todo ativo circulante.", "Liquidez seca fica entre as duas e exclui estoques do ativo circulante."], "calc": "Fórmula usual: (Ativo Circulante − Estoques − despesas antecipadas, quando aplicável) ÷ Passivo Circulante.", "correct": "C — indica quanto das dívidas de curto prazo poderia ser resgatado com os ativos de maior liquidez.", "wrong": "A e D descrevem liquidez imediata; B e E descrevem liquidez corrente.", "basis": "Análise de demonstrações contábeis — índices de liquidez.", "trap": "A expressão “bens e direitos de curto prazo” sem exclusão de estoques aponta para liquidez corrente, não seca."}'::jsonb WHERE id='3025525';
UPDATE questoes SET resolution='{"regra": "Na DRE, parte-se da receita bruta, deduzem-se as deduções para obter a receita líquida, subtrai-se o CMV para obter o lucro bruto, e depois as despesas e demais efeitos do resultado.", "passos": ["Receita bruta: R$ 270.000.", "Deduções: R$ 35.000. Receita líquida = R$ 235.000.", "CMV: R$ 120.000. Lucro bruto = R$ 115.000.", "Despesas operacionais: R$ 40.000. Resultado parcial = R$ 75.000.", "Outras receitas: R$ 15.000. Lucro líquido indicado pelos dados = R$ 90.000."], "calculo": "270.000 − 35.000 − 120.000 − 40.000 + 15.000 = R$ 90.000.", "correta": "D) lucro líquido de R$ 90.000,00.", "erradas": ["A) R$ 40.000 não resulta da sequência de apuração fornecida.", "B) Não há prejuízo: os efeitos líquidos apresentados produzem lucro.", "C) R$ 70.000 não corresponde à soma final dos efeitos informados."], "fundamento": "Estrutura de apuração do resultado e dados fornecidos no enunciado.", "pegadinha": "Não subtrair “outras receitas”: elas aumentam o resultado. Também não confundir receita bruta com receita líquida.", "cobranca": "DRE e destinação do resultado."}'::jsonb WHERE id='3457900';
UPDATE questoes SET resolution='{"regra": "Na ITG 2000 (R1), a transferência corrige conta indevidamente debitada ou creditada, transpondo o valor para a conta adequada, mantendo o lançamento em seus demais aspectos.", "passos": ["O valor total do lançamento está correto: R$ 8.000.", "O crédito na conta bancária também está correto.", "O erro está apenas na conta debitada: energia elétrica em vez de pessoal.", "A correção deve realocar o débito da conta errada para a conta correta, caracterizando lançamento de transferência."], "calculo": "R$ 8.000 permanecem como valor total; a correção é a transposição do débito de Despesas com Energia Elétrica para Despesas com Pessoal.", "correta": "A) Transferência.", "erradas": ["B) Ajuste extemporâneo: não é a forma de retificação indicada para simplesmente transferir o valor entre contas.", "C) Estorno: anularia o lançamento mediante lançamento inverso; não é necessário quando o valor está correto e apenas a conta está errada.", "D) Complementação: serve para ajustar valor anteriormente registrado, aumentando ou reduzindo-o."], "fundamento": "ITG 2000 (R1) — retificação por estorno, transferência e complementação. O CFC descreve transferência como a regularização da conta indevidamente debitada/creditada mediante transposição para a conta adequada.", "pegadinha": "Se o valor está certo e a conta está errada, pense em TRANSFERÊNCIA; se o lançamento inteiro precisa ser anulado, pense em ESTORNO.", "cobranca": "Escrituração — retificação de lançamento."}'::jsonb WHERE id='3598362';
UPDATE questoes SET resolution='{"regra": "O detalhamento da escrituração deve acompanhar a complexidade das operações e os requisitos de informação; não é inversamente proporcional. A ITG 2000 também admite códigos/abreviaturas uniformes e define estorno, transferência e complementação como formas de retificação.", "passos": ["A alternativa A afirma relação inversamente proporcional entre detalhamento e complexidade.", "A lógica normativa é compatibilidade com a complexidade das operações e necessidades de informação, portanto a afirmação está incorreta.", "B está de acordo com a exigência de que a terminologia expresse a essência econômica.", "C está de acordo com a escrituração descentralizada de unidades.", "D reproduz as três formas de retificação.", "E está de acordo com o uso de códigos/abreviaturas permanentes e uniformes."], "calculo": "Não há cálculo.", "correta": "A) é a alternativa INCORRETA.", "erradas": ["B) Correta.", "C) Correta.", "D) Correta.", "E) Correta."], "fundamento": "ITG 2000 (R1) — Escrituração Contábil. O CFC mantém a ITG 2000 (R1) entre as normas específicas.", "pegadinha": "A palavra “inversamente” é o erro: maior complexidade não implica menor detalhamento.", "cobranca": "Escrituração — ITG 2000 (R1)."}'::jsonb WHERE id='3862362';
UPDATE questoes SET resolution='{"regra": "Liquidez Corrente = Ativo Circulante / Passivo Circulante.", "passos": ["Capitais de terceiros = Passivo Exigível = R$ 1.400.000.", "Passivo Circulante = 25% × 1.400.000 = R$ 350.000.", "Ativo Total = 1,5 × 1.400.000 = R$ 2.100.000.", "Ativo Circulante = 30% × 2.100.000 = R$ 630.000.", "Liquidez Corrente = 630.000 / 350.000 = 1,80."], "calculo": "LC = 630.000 ÷ 350.000 = 1,80.", "correta": "B) 1,80.", "erradas": ["A) 1,90 não resulta da divisão dos valores apurados.", "C) 1,60 não corresponde à relação AC/PC.", "D) 1,70 não corresponde à relação AC/PC.", "E) 2,00 não corresponde à relação AC/PC."], "fundamento": "Fórmula do Índice de Liquidez Corrente: Ativo Circulante ÷ Passivo Circulante.", "pegadinha": "Não use Receita Líquida ou Lucro Líquido no cálculo da liquidez corrente; eles são dados acessórios.", "cobranca": "Índices de liquidez — cálculo."}'::jsonb WHERE id='2715255';
UPDATE questoes SET resolution='{"regra": "Liquidez Corrente = AC/PC; Liquidez Imediata = Disponível/PC; Liquidez Seca = (AC − Estoques)/PC; Liquidez Geral = (AC + ARLP)/(PC + PNC).", "passos": ["LC = 24.000/18.000 = 1,33, então I é falsa.", "LI = 3.000/18.000 = 0,1667 ≈ 0,17, então II é verdadeira.", "LS = (24.000 − 9.000)/18.000 = 15.000/18.000 = 0,83, então III é falsa.", "LG = (24.000 + 26.000)/(18.000 + 32.000) = 50.000/50.000 = 1,00, então IV é verdadeira."], "calculo": "LC=1,33; LI=0,17; LS=0,83; LG=1,00.", "correta": "A) II e IV, apenas.", "erradas": ["B) I é falsa e III também é falsa.", "C) III é falsa.", "D) I é falsa.", "E) I é falsa."], "fundamento": "Fórmulas dos índices de liquidez.", "pegadinha": "Liquidez seca exclui estoques; liquidez geral inclui o realizável a longo prazo e o passivo não circulante.", "cobranca": "Índices de liquidez — cálculo."}'::jsonb WHERE id='2415414';
UPDATE questoes SET resolution='{"regra": "Com Liquidez Corrente de 1,0 e Passivo Circulante de R$ 48.000, o Ativo Circulante é R$ 48.000. A Liquidez Seca de 0,80 indica ativo circulante menos estoques e despesas antecipadas igual a R$ 38.400.", "passos": ["AC = LC × PC = 1,0 × 48.000 = R$ 48.000.", "Ativo considerado na liquidez seca = 0,80 × 48.000 = R$ 38.400.", "Estoque = AC − ativo líquido da liquidez seca, considerando que as despesas pagas antecipadamente não foram divulgadas e não entram no cálculo líquido disponível.", "Estoque = 48.000 − 38.400 = R$ 9.600."], "calculo": "48.000 − (0,80 × 48.000) = 48.000 − 38.400 = R$ 9.600.", "correta": "D) R$ 9.600,00.", "erradas": ["A) R$ 24.000 é metade do AC, sem base na liquidez seca.", "B) R$ 48.000 corresponde ao AC, não ao estoque.", "C) R$ 86.400 excede o AC.", "E) R$ 33.600 corresponde à diferença entre AC e LI/valor, não ao estoque apurado."], "fundamento": "Liquidez corrente e liquidez seca.", "pegadinha": "Primeiro descubra o AC pela liquidez corrente; depois use a liquidez seca para chegar ao valor não estocado.", "cobranca": "Índices de liquidez — cálculo."}'::jsonb WHERE id='2415418';
UPDATE questoes SET resolution='{"regra": "O cálculo do capital de giro líquido (capital circulante líquido) é Ativo Circulante menos Passivo Circulante.", "passos": ["A questão informa que os dados necessários estão em uma tabela/figura anterior.", "Essa tabela não está presente no texto extraído disponibilizado para a resolução.", "Sem os valores de Ativo Circulante e Passivo Circulante de 2020 e 2021, não é possível reproduzir com segurança os valores de R$ 30.000, R$ 25.000 ou R$ 15.000.", "Portanto, a resolução deve ser conferida na imagem/tabela original antes de registrar uma alternativa como definitivamente correta."], "calculo": "CGL = AC − PC, mas os valores de AC e PC dos dois anos não estão disponíveis no texto extraído.", "correta": "Verificação necessária no quadro/tabela original da questão. O gabarito registrado no material é B, mas não é possível validar os números sem a tabela.", "erradas": ["A–E: não é seguro justificar ou eliminar as alternativas sem os dados da tabela original."], "fundamento": "Fórmula do Capital de Giro Líquido: Ativo Circulante − Passivo Circulante.", "pegadinha": "Questões com tabela/imagem exigem conferir os números originais; não substituir dados ausentes por suposições.", "cobranca": "Capital de giro líquido — cálculo com dados de tabela."}'::jsonb WHERE id='2415439';
UPDATE questoes SET resolution='{"regra": "Liquidez corrente = Ativo Circulante ÷ Passivo Circulante.", "passos": ["A liquidez corrente informada é 1,50.", "O Passivo Circulante é R$ 100.000.", "Isolando o Ativo Circulante: AC = 1,50 × 100.000 = R$ 150.000."], "calculo": "AC ÷ 100.000 = 1,50 → AC = R$ 150.000,00.", "correta": "C) R$ 150.000,00.", "erradas": ["A) R$ 66.666,67 corresponderia a dividir o passivo pelo índice.", "B) R$ 100.000 daria liquidez corrente de 1,00.", "D) R$ 77.000 daria 0,77.", "E) R$ 80.000 daria 0,80."], "fundamento": "Fórmula do índice de liquidez corrente: Ativo Circulante ÷ Passivo Circulante.", "pegadinha": "Quando o índice e o Passivo Circulante são dados, multiplique o passivo pelo índice para encontrar o ativo circulante.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='2431122';
UPDATE questoes SET resolution='{"regra": "Liquidez imediata = Disponibilidades ÷ Passivo Circulante.", "passos": ["Disponibilidades = R$ 50.000.", "Passivo Circulante = R$ 100.000.", "Dividindo 50.000 por 100.000, obtém-se 0,50."], "calculo": "50.000 ÷ 100.000 = 0,50.", "correta": "B) 0,50.", "erradas": ["A) 0,75 não corresponde à divisão apresentada.", "C) 0,25 não corresponde à razão entre os valores.", "D) 1,33 seria superior a 1 e não resulta dos dados.", "E) 1,50 também não resulta dos dados."], "fundamento": "Liquidez imediata = Disponibilidades ÷ Passivo Circulante.", "pegadinha": "Use apenas recursos imediatamente disponíveis; não inclua estoque ou contas a receber.", "cobranca": "Contabilidade Geral — liquidez imediata."}'::jsonb WHERE id='2431123';
UPDATE questoes SET resolution='{"regra": "Liquidez seca = (Ativo Circulante − Estoques) ÷ Passivo Circulante.", "passos": ["Ativo Circulante = R$ 200.000.", "Retira-se o estoque de R$ 40.000: AC sem estoque = R$ 160.000.", "Como a liquidez seca é 4,00, 160.000 ÷ PC = 4.", "Logo, PC = 160.000 ÷ 4 = R$ 40.000."], "calculo": "PC = (200.000 − 40.000) ÷ 4,00 = R$ 40.000,00.", "correta": "D) R$ 40.000,00.", "erradas": ["A) R$ 100.000 produziria liquidez seca de 1,60.", "B) R$ 60.000 produziria 2,67.", "C) R$ 160.000 produziria 1,00.", "E) R$ 50.000 produziria 3,20."], "fundamento": "Liquidez seca = (Ativo Circulante − Estoques) ÷ Passivo Circulante.", "pegadinha": "Primeiro retire o estoque; só depois use o índice para encontrar o passivo.", "cobranca": "Contabilidade Geral — liquidez seca."}'::jsonb WHERE id='2431124';
UPDATE questoes SET resolution='{"regra": "Liquidez geral = (Ativo Circulante + Realizável a Longo Prazo) ÷ (Passivo Circulante + Passivo Não Circulante).", "passos": ["Os ativos considerados somam 100.000 + 200.000 = R$ 300.000.", "A liquidez geral é 1,00.", "Portanto, o total dos passivos considerados também deve ser R$ 300.000.", "Como o Passivo Circulante já é R$ 300.000, o Passivo Não Circulante é R$ 0."], "calculo": "300.000 ÷ (300.000 + PNC) = 1,00 → PNC = R$ 0,00.", "correta": "A) R$ 0,00.", "erradas": ["B) R$ 300.000 faria o índice cair para 0,50.", "C) R$ 200.000 faria o índice cair para 0,60.", "D) R$ 100.000 faria o índice cair para 0,75.", "E) R$ 50.000 faria o índice ficar abaixo de 1."], "fundamento": "Liquidez geral = (AC + RLP) ÷ (PC + PNC).", "pegadinha": "A liquidez geral considera também os elementos de longo prazo; não confundir com liquidez corrente.", "cobranca": "Contabilidade Geral — liquidez geral."}'::jsonb WHERE id='2431125';
UPDATE questoes SET resolution='{"regra": "Liquidez corrente = Ativo Circulante ÷ Passivo Circulante.", "passos": ["A própria questão define o índice pela divisão do Ativo Circulante pelo Passivo Circulante.", "Essa é a fórmula da liquidez corrente."], "calculo": "Não há valores para calcular.", "correta": "B) Índice de liquidez corrente.", "erradas": ["A) Liquidez seca exclui estoques do ativo circulante.", "C) Liquidez geral inclui também os elementos de longo prazo.", "D) Liquidez imediata considera disponibilidades.", "E) “Liquidez circulante” não é a denominação usada na fórmula apresentada; a resposta esperada pelo caderno é liquidez corrente."], "fundamento": "Análise das demonstrações contábeis — índice de liquidez corrente.", "pegadinha": "Identifique a fórmula antes de olhar as alternativas.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1119771';
UPDATE questoes SET resolution='{"regra": "Liquidez imediata = Disponibilidades ÷ Passivo Circulante.", "passos": ["A questão descreve caixa, conta corrente e aplicações de curtíssimo prazo como recursos imediatamente disponíveis.", "A fórmula indicada é Disponibilidades ÷ Passivo Circulante.", "Esse indicador é a liquidez imediata."], "calculo": "Não há valores para calcular.", "correta": "D) Índice de liquidez imediata.", "erradas": ["A) Liquidez seca retira estoques.", "B) Liquidez corrente usa todo o Ativo Circulante.", "C) Liquidez geral considera curto e longo prazo.", "E) Não corresponde à fórmula apresentada."], "fundamento": "Análise das demonstrações contábeis — liquidez imediata.", "pegadinha": "“Disponibilidades” é a palavra-chave para liquidez imediata.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1119773';
UPDATE questoes SET resolution='{"regra": "Patrimônio Líquido = Ativo Total − Passivo Exigível; liquidez geral = (AC + RLP) ÷ (PC + PNC).", "passos": ["Ativo Total = 20.000 + 80.000 + 90.000 = R$ 190.000.", "Passivo Exigível = 50.000 + 50.000 = R$ 100.000.", "PL = 190.000 − 100.000 = R$ 90.000.", "Liquidez geral = (20.000 + 80.000) ÷ (50.000 + 50.000) = 1,00."], "calculo": "PL = R$ 90.000; LG = R$ 100.000 ÷ R$ 100.000 = 1,0000.", "correta": "C) R$ 90.000,00 e 1,0000.", "erradas": ["A) Confunde o ativo total com o PL.", "B) O PL não é R$ 150.000.", "D) R$ 50.000 é incompatível com a equação patrimonial.", "E) A liquidez geral não é 0,9000."], "fundamento": "Equação patrimonial e fórmula da liquidez geral.", "pegadinha": "Calcule primeiro o ativo total e o passivo exigível; depois aplique a equação patrimonial.", "cobranca": "Contabilidade Geral — equação patrimonial e liquidez."}'::jsonb WHERE id='1119807';
UPDATE questoes SET resolution='{"regra": "Liquidez geral = (AC + RLP) ÷ (PC + PNC); liquidez corrente = AC ÷ PC; liquidez seca = (AC − estoques) ÷ PC; liquidez imediata = Disponibilidades ÷ PC.", "passos": ["AC = 20.000 + 10.000 + 0 = R$ 30.000.", "RLP = R$ 2.000; PC = R$ 500.000; PNC = R$ 50.000.", "LG = 32.000 ÷ 550.000 ≈ 0,0582.", "LC = 30.000 ÷ 500.000 = 0,0600.", "Como estoque é zero, LS = 30.000 ÷ 500.000 = 0,0600.", "LI = 20.000 ÷ 500.000 = 0,0400."], "calculo": "LG ≈ 0,0582; LC = 0,0600; LS = 0,0600; LI = 0,0400.", "correta": "E) 0,0582; 0,0600; 0,0600; 0,0400.", "erradas": ["A) A liquidez geral está errada e a sequência não corresponde aos cálculos.", "B) LC e LS não são 0,04 e 0,03.", "C) Liquidez imediata não é 1,04.", "D) A sequência de liquidez seca e imediata está incorreta."], "fundamento": "Fórmulas dos índices de liquidez.", "pegadinha": "Estoque zero faz liquidez seca ser igual à liquidez corrente.", "cobranca": "Contabilidade Geral — cálculo de índices de liquidez."}'::jsonb WHERE id='1119810';
UPDATE questoes SET resolution='{"regra": "Para PC = 30.000 + 40.000 + 80.000 = R$ 150.000 e AC = 240.000 + 80.000 + 170.000 = R$ 490.000, os índices devem ser calculados diretamente pelas fórmulas.", "passos": ["PC = adiantamentos de clientes + fornecedores + salários = R$ 150.000.", "AC = caixa/equivalentes + aplicações de alta liquidez + estoque = R$ 490.000.", "Liquidez corrente = 490.000 ÷ 150.000 ≈ 3,27.", "Liquidez imediata = (240.000 + 80.000) ÷ 150.000 ≈ 2,13.", "Liquidez seca = (490.000 − 170.000) ÷ 150.000 ≈ 2,13.", "Liquidez geral = (490.000 + 45.000) ÷ (150.000 + 180.000) ≈ 1,62."], "calculo": "LG ≈ 1,62; LC ≈ 3,27; LS ≈ 2,13; LI ≈ 2,13.", "correta": "D) A liquidez geral de aproximadamente 2,85 é a alternativa INCORRETA.", "erradas": ["A) Correta: LC ≈ 3,27.", "B) Correta: LI ≈ 2,13.", "C) Correta: LS ≈ 2,13."], "fundamento": "Fórmulas dos índices de liquidez e classificação das contas do balanço.", "pegadinha": "Para liquidez geral, não use apenas o Passivo Circulante: entram PC + PNC.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1972598';
UPDATE questoes SET resolution='{"regra": "Os índices tradicionais de liquidez são liquidez corrente, seca, imediata e geral.", "passos": ["Liquidez corrente: AC ÷ PC.", "Liquidez seca: (AC − estoques) ÷ PC.", "Liquidez imediata: disponibilidades ÷ PC.", "Liquidez geral: (AC + RLP) ÷ (PC + PNC).", "“Liquidez progressiva” não integra o conjunto tradicional de índices apresentado pela questão."], "calculo": "Não há cálculo.", "correta": "C) Liquidez progressiva.", "erradas": ["A) Liquidez corrente é índice tradicional.", "B) Liquidez seca é índice tradicional.", "D) Liquidez imediata é índice tradicional."], "fundamento": "Análise das demonstrações contábeis — índices de liquidez.", "pegadinha": "A banca pode inserir um nome plausível, mas não padronizado, entre indicadores conhecidos.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1058161';
UPDATE questoes SET resolution='{"regra": "Liquidez corrente = AC ÷ PC; liquidez seca = (AC − estoques) ÷ PC.", "passos": ["AC = disponibilidades 500.000 + duplicatas a receber até 365 dias 30.000 + estoque 200.000 = R$ 730.000.", "PC = salários 50.000 + duplicatas a pagar 20.000 + empréstimos até 365 dias 250.000 = R$ 320.000.", "LC = 730.000 ÷ 320.000 = 2,28125 ≈ 2,28.", "LS = (730.000 − 200.000) ÷ 320.000 = 1,65625 ≈ 1,66."], "calculo": "LC ≈ 2,28; LS ≈ 1,66.", "correta": "A) 2,28 e 1,66.", "erradas": ["B) Os dois índices estão subestimados.", "C) Liquidez seca não pode ser 0,31 com esses dados.", "D) Os valores não correspondem às fórmulas."], "fundamento": "Fórmulas dos índices de liquidez corrente e seca.", "pegadinha": "Para PC, entram somente as obrigações até 365 dias; o empréstimo de longo prazo fica fora.", "cobranca": "Contabilidade Geral — liquidez corrente e seca."}'::jsonb WHERE id='1273148';
UPDATE questoes SET resolution='{"regra": "Liquidez seca mede a capacidade de pagamento no curto prazo desconsiderando os estoques do Ativo Circulante.", "passos": ["A característica descrita é justamente excluir estoques, que podem ter menor liquidez ou obsolescência.", "A fórmula é (AC − estoques) ÷ PC."], "calculo": "Não há cálculo.", "correta": "A) Liquidez Seca.", "erradas": ["B) Liquidez corrente inclui estoques no AC.", "C) Liquidez imediata considera apenas disponibilidades.", "D) Liquidez geral incorpora longo prazo."], "fundamento": "Análise das demonstrações contábeis — liquidez seca.", "pegadinha": "“Desconsiderando estoques” é a expressão-chave.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1273153';
UPDATE questoes SET resolution='{"regra": "Liquidez imediata = Disponibilidades ÷ Passivo Circulante.", "passos": ["A questão fornece exatamente a fórmula do índice.", "Disponibilidades são caixa e equivalentes e outros recursos de disponibilidade imediata, conforme a classificação adotada."], "calculo": "Não há cálculo.", "correta": "C) Liquidez Imediata.", "erradas": ["A) Liquidez seca exclui estoques, mas inclui outros ativos circulantes.", "B) Liquidez corrente usa o AC integral.", "D) Liquidez geral inclui longo prazo."], "fundamento": "Análise das demonstrações contábeis — liquidez imediata.", "pegadinha": "A palavra “Disponibilidades” diferencia a liquidez imediata das demais.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1273155';
UPDATE questoes SET resolution='{"regra": "Liquidez corrente = Ativo Circulante ÷ Passivo Circulante.", "passos": ["A fórmula descrita é a definição clássica do índice de liquidez corrente.", "Não são excluídos estoques nem incluídas contas de longo prazo."], "calculo": "Não há cálculo.", "correta": "B) Liquidez Corrente.", "erradas": ["A) Liquidez seca exclui estoques.", "C) Liquidez imediata usa apenas disponibilidades.", "D) Liquidez geral inclui RLP e PNC."], "fundamento": "Análise das demonstrações contábeis — liquidez corrente.", "pegadinha": "AC ÷ PC é a fórmula que deve ser reconhecida imediatamente.", "cobranca": "Contabilidade Geral — índices de liquidez."}'::jsonb WHERE id='1273156';
UPDATE questoes SET resolution='{"regra": "Liquidez corrente = Ativo Circulante ÷ Passivo Circulante.", "passos": ["AC = caixa/equivalentes 12.200 + estoque 11.100 + adiantamento a fornecedores 14.400 = R$ 37.700.", "PC = fornecedores 28.300 + salários/encargos 33.400 + adiantamento de clientes 15.500 = R$ 77.200.", "Liquidez corrente = 37.700 ÷ 77.200 ≈ 0,4883.", "Arredondando para duas casas: 0,49."], "calculo": "R$ 37.700 ÷ R$ 77.200 ≈ 0,49.", "correta": "D) 0,49.", "erradas": ["A) 0,15 não corresponde à razão entre AC e PC.", "B) 0,20 não corresponde aos saldos.", "C) 0,38 não corresponde aos saldos.", "E) 0,51 não corresponde ao arredondamento correto."], "fundamento": "Liquidez corrente = Ativo Circulante ÷ Passivo Circulante.", "pegadinha": "Adiantamento a fornecedores é ativo; adiantamento de clientes é passivo. Não os troque na montagem do AC e PC.", "cobranca": "Contabilidade Geral — liquidez corrente e classificação patrimonial."}'::jsonb WHERE id='1335873';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o Índice de Liquidez Corrente (ILC): Ativo Circulante ÷ Passivo Circulante.", "rule": "ILC = AC / PC. Entram no AC os itens realizáveis no curto prazo; no PC, as obrigações exigíveis no curto prazo.", "reasoning": ["AC = Disponibilidades 120.000 + Aplicações de curto prazo 40.000 + Clientes 90.000 + Empréstimos de curto prazo concedidos 60.000 = R$ 310.000.", "PC = Fornecedores 100.000 + Salários a pagar 40.000 + Dividendos a pagar 30.000 = R$ 170.000.", "ILC = 310.000 / 170.000 = 1,8235, aproximadamente 1,82."], "calculation": "AC = Disponibilidades 120.000 + Aplicações de curto prazo 40.000 + Clientes 90.000 + Empréstimos de curto prazo concedidos 60.000 = R$ 310.000.", "correct_answer": "C — 1,82.", "why_wrong": "A, B, D e E apresentam valores que não resultam da divisão do Ativo Circulante de R$ 310 mil pelo Passivo Circulante de R$ 170 mil.", "basis": "Análise de índices de liquidez e classificação patrimonial dos itens do enunciado.", "fafipa_trap": "Não incluir veículos e intangível no AC apenas porque são ativos; ambos são não circulantes neste contexto.", "verification": null}'::jsonb WHERE id='1336861';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o Índice de Liquidez Geral (ILG), que considera recursos de curto e longo prazo em relação às obrigações de curto e longo prazo.", "rule": "ILG = (Ativo Circulante + Realizável a Longo Prazo) / (Passivo Circulante + Passivo Não Circulante).", "reasoning": ["AC = 120.000 + 40.000 + 60.000 + 90.000 = R$ 310.000.", "Realizável a longo prazo: o empréstimo adquirido de longo prazo, no valor de R$ 100.000, é tratado como direito da entidade.", "PC = 100.000 + 60? Não: o item de R$ 60.000 é empréstimo de curto prazo concedido, portanto é ativo. PC = fornecedores 100.000 + salários 40.000 + dividendos 30.000 = R$ 170.000.", "Passivo não circulante não aparece no quadro; portanto o denominador permanece R$ 170.000.", "ILG = (310.000 + 100.000) / 170.000 = 2,41, o que não corresponde às alternativas. Isso revela que a classificação/extração do item “Empréstimos adquiridos de Longo Prazo” precisa ser conferida no original."], "calculation": "AC = 120.000 + 40.000 + 60.000 + 90.000 = R$ 310.000.", "correct_answer": "B — 1,15 (gabarito registrado no material), mas o cálculo não é reproduzível com segurança a partir do texto extraído.", "why_wrong": "As demais alternativas também não podem ser validadas sem confirmar a natureza do item de R$ 100.000 e a apresentação original da tabela.", "basis": "Índice de Liquidez Geral: (AC + RLP)/(PC + PNC).", "fafipa_trap": "Não transformar automaticamente um “empréstimo adquirido de longo prazo” em direito; a expressão pode indicar obrigação. Conferir o quadro original é indispensável.", "verification": "Verificar no PDF/questão original antes de considerar o gabarito definitivo."}'::jsonb WHERE id='1336862';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular depreciação, impairment e resultado na venda de imobilizado.", "rule": "Depreciação linear = (custo − valor residual) / vida útil. O valor recuperável é o maior entre valor em uso e valor justo líquido de despesas de venda. Se o valor contábil superar o recuperável, reconhece-se perda por impairment.", "reasoning": ["Depreciação anual = (600.000 − 40.000) / 8 = 70.000.", "Valor contábil antes do impairment em 31/12/2024 = 600.000 − 70.000 = 530.000.", "Valor recuperável = maior entre 520.000 e 510.000 = 520.000.", "Perda por impairment = 530.000 − 520.000 = 10.000.", "Valor contábil após impairment = 520.000.", "Venda por 530.000 gera ganho de 10.000."], "calculation": "(600.000−40.000)/8 = 70.000; 600.000−70.000 = 530.000; recuperável = 520.000; impairment = 10.000; 530.000−520.000 = ganho de 10.000.", "correct_answer": "B — Ganho de R$ 10.000,00.", "why_wrong": "A ignora o impairment; C, D e E não correspondem ao valor contábil após o teste de recuperabilidade.", "basis": "NBC TG 27 — Ativo Imobilizado; NBC TG 01 — Redução ao Valor Recuperável de Ativos.", "fafipa_trap": "Aplicar o impairment antes da venda e usar o maior entre valor em uso e valor justo líquido de despesas de venda.", "verification": "Cálculo reproduzido diretamente dos valores do enunciado."}'::jsonb WHERE id='3435140';
UPDATE questoes SET resolution='{"what_it_tests": "Aplicar mudança de estimativa de vida útil e valor residual na depreciação.", "rule": "Mudanças de estimativas contábeis são aplicadas prospectivamente. A depreciação acumulada anterior não é recalculada; a nova base depreciável é distribuída pela vida útil remanescente.", "reasoning": ["Custo = 72.000 e residual inicial = 8.000, então depreciação anual inicial = 64.000/8 = 8.000.", "Em 31/12/2024, após dois anos, depreciação acumulada = 16.000 e valor contábil = 56.000.", "A nova estimativa indica residual de 12.000 e vida útil remanescente de 4 anos.", "Nova depreciação anual = (56.000−12.000)/4 = 11.000.", "Em 2025, a acumulada passa a 16.000 + 11.000 = 27.000."], "calculation": "Depreciação 2023/2024: 2×8.000 = 16.000; valor contábil = 56.000; 2025 = (56.000−12.000)/4 = 11.000; acumulada = 27.000.", "correct_answer": "A — R$ 27.000,00.", "why_wrong": "As demais alternativas não aplicam prospectivamente a revisão das estimativas.", "basis": "NBC TG 23 — Políticas Contábeis, Mudança de Estimativa e Retificação de Erro; NBC TG 27.", "fafipa_trap": "Recalcular retroativamente a depreciação depois da mudança de estimativa.", "verification": "Cálculo reproduzido diretamente do enunciado."}'::jsonb WHERE id='3597759';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular depreciação e perda por impairment de máquina.", "rule": "A depreciação linear usa custo menos valor residual. O valor recuperável é o maior entre valor em uso e valor justo líquido de despesas de venda.", "reasoning": ["Depreciação anual = (600.000−100.000)/10 = 50.000.", "Valor contábil antes do impairment = 600.000−50.000 = 550.000.", "Valor recuperável = maior entre 520.000 e 505.000 = 520.000.", "Perda por impairment = 550.000−520.000 = 30.000."], "calculation": "(600.000−100.000)/10 = 50.000; 600.000−50.000 = 550.000; 550.000−520.000 = 30.000.", "correct_answer": "B — Depreciação anual de R$ 50.000,00 e perda por impairment de R$ 30.000,00.", "why_wrong": "A não reconhece a perda; C usa valor recuperável ou cálculo incorreto; D superestima a depreciação.", "basis": "NBC TG 27 — Ativo Imobilizado; NBC TG 01 — Redução ao Valor Recuperável de Ativos.", "fafipa_trap": "Usar o menor valor entre valor em uso e valor justo líquido, quando a norma manda usar o maior para o valor recuperável.", "verification": "Cálculo reproduzido diretamente do enunciado."}'::jsonb WHERE id='3598360';
UPDATE questoes SET resolution='{"regra": "No reconhecimento inicial, o ativo imobilizado é mensurado pelo custo quando os critérios de reconhecimento são atendidos. O valor de mercado posterior não transforma automaticamente a base inicial em valor justo.", "passos": ["Custo de aquisição = R$ 84.000.", "Transporte, instalação e testes necessários = R$ 6.000.", "Custo inicial = R$ 90.000.", "A depreciação acumulada de R$ 9.000 reduz o valor contábil, mas não muda a base de mensuração inicial.", "O laudo de R$ 98.000 é informação posterior e não é a base indicada para o reconhecimento inicial descrito."], "calculo": "Custo = 84.000 + 6.000 = R$ 90.000; valor contábil após depreciação = 90.000 − 9.000 = R$ 81.000.", "correta": "A — custo histórico.", "erradas": ["B) Valor justo não é a base indicada para o reconhecimento inicial do equipamento nesse caso.", "C) Valor em uso é mensuração baseada em fluxos de caixa e não corresponde ao valor de mercado informado.", "D) Custo corrente não é a base indicada pelo enunciado."], "fundamento": "NBC TG 27 — Ativo Imobilizado; estrutura de mensuração pelo custo no reconhecimento inicial.", "pegadinha": "Não confunda “valor de mercado” apurado depois com a base de reconhecimento inicial pelo custo.", "cobranca": "Contabilidade Geral — Ativo Imobilizado."}'::jsonb WHERE id='3598356';
UPDATE questoes SET resolution='{"regra": "Integram o custo do imobilizado os gastos diretamente atribuíveis para colocar o ativo no local e condição necessários ao funcionamento. Gastos administrativos gerais não integram o custo.", "passos": ["Aquisição: R$ 55.000.", "Transporte e instalação: R$ 4.800 — diretamente atribuíveis.", "Aprovação administrativa: R$ 1.500 — não entra no custo, conforme o enunciado.", "Teste de funcionamento: R$ 1.200 — diretamente atribuível.", "Somatório capitalizável = 55.000 + 4.800 + 1.200."], "calculo": "R$ 55.000 + R$ 4.800 + R$ 1.200 = R$ 61.000.", "correta": "A — R$ 61.000,00.", "erradas": ["B) Ignora transporte, instalação e teste.", "C) Inclui o gasto administrativo de R$ 1.500, que não deve ser capitalizado.", "D) Exclui o teste de funcionamento."], "fundamento": "NBC TG 27 (R4), custos diretamente atribuíveis ao ativo imobilizado.", "pegadinha": "A palavra-chave é “diretamente atribuível”. Gastos administrativos gerais não devem ser incorporados.", "cobranca": "Contabilidade Geral — Ativo Imobilizado."}'::jsonb WHERE id='3598373';
UPDATE questoes SET resolution='{"regra": "Valor depreciável é o custo de um ativo, ou outro valor que substitua o custo, menos seu valor residual.", "passos": ["Identifique o conceito pedido: valor depreciável.", "Subtraia o valor residual do custo ou do valor que o substitua.", "Isso corresponde literalmente à alternativa D."], "calculo": "Valor depreciável = custo (ou valor substituto) − valor residual.", "correta": "D — custo de um ativo ou outro valor que substitua o custo, menos seu valor residual.", "erradas": ["A) Define valor residual.", "B) Define valor contábil.", "C) Define valor justo."], "fundamento": "NBC TG 27 (R4), definição de valor depreciável e conceitos relacionados.", "pegadinha": "Compare as definições: A = residual; B = contábil; C = justo; D = depreciável.", "cobranca": "Contabilidade Geral — depreciação."}'::jsonb WHERE id='3598376';
UPDATE questoes SET resolution='{"regra": "Na Estrutura Conceitual, o reconhecimento de receita ou despesa pode ocorrer simultaneamente ao reconhecimento/aumento de ativo ou passivo, ou ao desreconhecimento/diminuição desses elementos.", "passos": ["I: receita pode ocorrer com reconhecimento inicial ou aumento de ativo — verdadeiro.", "II: receita pode ocorrer com desreconhecimento ou diminuição de passivo — verdadeiro.", "III: despesa pode ocorrer com reconhecimento inicial ou aumento de passivo — verdadeiro.", "IV: despesa pode ocorrer com desreconhecimento ou diminuição de ativo — verdadeiro.", "Todas as assertivas estão corretas."], "calculo": "Não há cálculo.", "correta": "C — I, II, III e IV.", "erradas": ["A) Omite I, II e IV, que também são verdadeiras.", "B) Omite I e IV.", "D) Considera apenas I.", "E) Omite II e III."], "fundamento": "NBC TG Estrutura Conceitual — relação entre reconhecimento de receitas/despesas e mudanças em ativos e passivos.", "pegadinha": "Não memorize apenas “receita = entrada de dinheiro”. A Estrutura Conceitual trabalha com mudanças em ativos e passivos, inclusive desreconhecimento.", "cobranca": "Contabilidade Geral — Estrutura Conceitual."}'::jsonb WHERE id='3120009';
UPDATE questoes SET resolution='{"regra": "A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.", "passos": ["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — V, V, F, V.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb WHERE id='3708572';
UPDATE questoes SET resolution='{"regra": "A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.", "passos": ["Identifique o núcleo do tema: Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — Descontos comerciais e abatimentos devem ser deduzidos na determinação do custo de aquisição.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade Geral - CPC 16 - Tratamento Contábil para os Estoques"}'::jsonb WHERE id='3708599';
